import numpy as np

class CoordinateDescentSeparableOptimization:
    def __init__(self, budget=10000, dim=10):
        self.budget = budget
        self.dim = dim
        self.lb = -5.0
        self.ub = 5.0

    def __call__(self, func):
        x_opt = np.random.uniform(self.lb, self.ub, size=self.dim)
        f_opt = func(x_opt)

        for _ in range(self.budget):
            for i in range(self.dim):
                grid = np.linspace(self.lb, self.ub, num=100)
                f_values = [func(np.array([x if j == i else x_opt[j] for j in range(self.dim)])) for x in grid]
                x_opt[i] = grid[np.argmin(f_values)]
            f_new = func(x_opt)
            if f_new < f_opt:
                f_opt = f_new
        return f_opt, x_opt

import numpy as np

class CoordinateDescentSeparable:
    def __init__(self, budget=10000, dim=10):
        self.budget = budget
        self.dim = dim
        self.bounds = [-5.0, 5.0]

    def __call__(self, func):
        x = np.random.uniform(*self.bounds, size=self.dim)
        f_opt = func(x)
        x_opt = x.copy()

        for _ in range(self.budget):
            for i in range(self.dim):
                # Save the current value and initialize best value with it
                x_orig, x[i] = x[i], np.random.uniform(*self.bounds)
                f = func(x)

                # If new value is better, keep it; otherwise revert to original
                if f < f_opt:
                    f_opt = f
                    x_opt[i] = x[i]
                else:
                    x[i] = x_orig
        return f_opt, x_opt

