import numpy as np

class SimplifiedAdaptiveCoordinateDescentSeparable:
    def __init__(self, budget=10000, dim=10):
        self.budget = budget
        self.dim = dim
        self.bounds = [-5.0, 5.0]
        self.step_size = (self.bounds[1] - self.bounds[0]) / 2  # Initial step size

    def __call__(self, func):
        x = np.random.uniform(*self.bounds, size=self.dim)
        f_opt = func(x)
        x_opt = x.copy()

        for _ in range(self.budget):
            dimensions = np.random.permutation(self.dim)  # Randomize dimension order
            for i in dimensions:
                step = np.random.uniform(-1, 1) * self.step_size
                x[i] += step
                if x[i] < self.bounds[0]: x[i] = self.bounds[0] + np.abs(step)  # Bound check and correct
                elif x[i] > self.bounds[1]: x[i] = self.bounds[1] - np.abs(step)

                f = func(x)
                if f < f_opt:
                    f_opt = f
                    x_opt[i] = x[i]
                else:
                    x[i] -= step  # Revert back if no improvement
            self.step_size *= 0.995  # Decrease step size for better convergence
        return f_opt, x_opt

import numpy as np

class CoordinateDescent:
    def __init__(self, budget=10000, dim=10, step_size=0.1):
        self.budget = budget
        self.dim = dim
        self.step_size = step_size  # Step size for searching within a dimension

    def __call__(self, func):
        x = np.random.uniform(func.bounds.lb, func.bounds.ub, self.dim)
        f_opt = func(x)
        x_opt = x.copy()

        for _ in range(self.budget):
            for i in range(self.dim):
                # Backup current dimension value
                temp = x[i]

                # Move left and check improvement
                x[i] -= self.step_size
                f_left = func(x)
                if f_left < f_opt:
                    f_opt = f_left
                else:
                    x[i] = temp  # Revert to original value if no improvement

                # Move right and check improvement
                x[i] += 2 * self.step_size
                f_right = func(x)
                if f_right < f_opt:
                    f_opt = f_right
                else:
                    x[i] = temp  # Revert to original value if no improvement

        return f_opt, x_opt

