class EnhancedCoordinateDescent:
    def __init__(self, budget=10000, dim=10, step_size=0.1):
        self.budget = budget
        self.dim = dim
        self.step_size = step_size

    def __call__(self, func):
        x = np.random.uniform(func.bounds.lb, func.bounds.ub, self.dim)
        f_opt = func(x)
        x_opt = x.copy()

        for _ in range(self.budget):
            for i in range(self.dim):
                direction = np.sign(np.random.randn())  # Randomly choose search direction based on standard normal distribution
                temp = x[i]

                # Move and check improvement
                x[i] += direction * self.step_size
                f_new = func(x)
                if f_new < f_opt:
                    f_opt = f_new
                    x_opt = x.copy()
                else:
                    x[i] = temp  # Revert to original value if no improvement
        return f_opt, x_opt

import numpy as np

class AdaptiveLocalSearchOptimizer:
    def __init__(self, budget=10000, dim=10, min_epsilon=0.01, max_epsilon=1.0):
        self.budget = budget
        self.dim = dim
        self.min_epsilon = min_epsilon  # Minimum adaptive step size
        self.max_epsilon = max_epsilon  # Maximum adaptive step size

    def __call__(self, func):
        self.f_opt = np.inf
        self.x_opt = np.random.uniform(-5, 5, size=self.dim)
        epsilon = self.max_epsilon
        for i in range(self.budget):
            x = self.explore(func, epsilon) if i < int(0.75 * self.budget) else self.refine(func, epsilon)
            f = func(x)
            if f < self.f_opt:
                self.f_opt = f
                self.x_opt = x
                epsilon *= 1.05  # Increase step size if improvement is found
            else:
                epsilon *= 0.95  # Decrease step size if no improvement is found
        return self.f_opt, self.x_opt

    def explore(self, func, epsilon):
        return np.random.uniform(-5, 5, size=self.dim)

    def refine(self, func, epsilon):
        x = self.x_opt + np.random.normal(0, epsilon, size=self.dim)
        return np.clip(x, -5, 5)

import numpy as np

class AdaptiveCoordinateDescent:
    def __init__(self, budget=10000, dim=10, initial_step_size=0.2, restart_probability=0.2):
        self.budget = budget
        self.dim = dim
        self.initial_step_size = initial_step_size
        self.restart_probability = restart_probability

    def __call__(self, func):
        best_solution = np.random.uniform(func.bounds.lb, func.bounds.ub)
        best_fitness = func(best_solution)
        step_size = self.initial_step_size

        for _ in range(self.budget - 1):
            if np.random.rand() < self.restart_probability:
                x = np.random.uniform(func.bounds.lb, func.bounds.ub)
            else:
                idx = np.random.randint(0, self.dim)
                direction = np.random.choice([-1, 1])
                x = best_solution + step_size * direction * np.eye(self.dim)[idx]
            f = func(x)

            if f < best_fitness:
                best_solution = x
                best_fitness = f
                step_size *= 1.2
            else:
                step_size *= 0.8

        return best_fitness, best_solution

