class ImprovedAdaptiveLocalSearchOptimizer:
    def __init__(self, budget=10000, dim=10):
        self.budget = budget
        self.dim = dim
        self.epsilon = 1.0  # Initial adaptive step size

    def __call__(self, func):
        self.f_opt = np.inf
        self.x_opt = np.random.uniform(-5, 5, size=self.dim)
        for i in range(self.budget):
            x = self.explore() if i < int(0.75 * self.budget) else self.refine()
            f = func(x)
            if f < self.f_opt:
                self.f_opt = f
                self.x_opt = x
        return self.f_opt, self.x_opt

    def explore(self):
        return np.random.uniform(-5, 5, size=self.dim)

    def refine(self):
        x = self.x_opt + np.random.normal(0, self.epsilon, size=self.dim)
        self.epsilon *= 1.02 if x[0] < self.x_opt[0] else 0.98  # Adapt step size based on improvement in the first dimension
        return np.clip(x, -5, 5)

