class AdaptiveCoordinateSearchOptimized:
    def __init__(self, budget=10000, dim=10, initial_step_size=0.5, restart_probability=0.02):
        self.budget = budget
        self.dim = dim
        self.initial_step_size = initial_step_size
        self.restart_probability = restart_probability

    def __call__(self, func):
        x = np.random.uniform(func.bounds.lb, func.bounds.ub)
        f = func(x)
        self.f_opt = f
        self.x_opt = x
        step_sizes = np.full(self.dim, self.initial_step_size)

        for _ in range(self.budget - 1):
            if np.random.rand() < self.restart_probability:
                x = np.random.uniform(func.bounds.lb, func.bounds.ub)
                step_sizes = np.full(self.dim, self.initial_step_size)
            else:
                idx = np.random.randint(0, self.dim)
                x_new = x.copy()
                x_new[idx] += np.random.choice([-1, 1]) * step_sizes[idx]
                f_new = func(x_new)

                if f_new < f:
                    f, x = f_new, x_new
                    step_sizes *= 1.2
                else:
                    step_sizes[idx] *= 0.8

            if f < self.f_opt:
                self.f_opt, self.x_opt = f, x

        return self.f_opt, self.x_opt

import numpy as np

class AdaptiveDE_LocalSearch:
    def __init__(self, budget=10000, dim=10, pop_size=40, initial_de_rate=0.7, initial_ls_radius=0.1):
        self.budget = budget
        self.dim = dim
        self.pop_size = pop_size
        self.de_rate = initial_de_rate
        self.ls_radius = initial_ls_radius
        self.population = None
        self.fitness = None
        self.f_opt = np.Inf
        self.x_opt = None
        self.eval_count = 0
        self.success_history = []

    def initialize_population(self, func):
        self.population = np.random.uniform(func.bounds.lb, func.bounds.ub, size=(self.pop_size, self.dim))
        self.fitness = np.array([func(x) for x in self.population])
        self.eval_count += self.pop_size
        self.update_best(func)

    def differential_evolution(self, func):
        for i in range(self.pop_size):
            if self.eval_count >= self.budget:
                break

            idxs = np.random.choice(self.pop_size, 3, replace=False)
            x_r1, x_r2, x_r3 = self.population[idxs]

            x_mutated = x_r1 + self.de_rate * (x_r2 - x_r3)
            x_mutated = np.clip(x_mutated, func.bounds.lb, func.bounds.ub)

            j_rand = np.random.randint(self.dim)
            x_trial = np.copy(self.population[i])
            for j in range(self.dim):
                if np.random.rand() < 0.1 or j == j_rand:
                    x_trial[j] = x_mutated[j]

            f_trial = func(x_trial)
            self.eval_count += 1

            if f_trial < self.fitness[i]:
                self.population[i] = x_trial
                self.fitness[i] = f_trial
                self.success_history.append(1)
                self.update_best(func)
            else:
                self.success_history.append(0)

    def local_search(self, func):
        if self.x_opt is None:
            return

        if self.eval_count >= self.budget:
            return

        x_perturbed = self.x_opt + np.random.uniform(-self.ls_radius, self.ls_radius, size=self.dim)
        x_perturbed = np.clip(x_perturbed, func.bounds.lb, func.bounds.ub)
        f_perturbed = func(x_perturbed)
        self.eval_count += 1

        if f_perturbed < self.f_opt:
            self.f_opt = f_perturbed
            self.x_opt = x_perturbed

    def update_best(self, func):
        best_index = np.argmin(self.fitness)
        if self.fitness[best_index] < self.f_opt:
            self.f_opt = self.fitness[best_index]
            self.x_opt = self.population[best_index]

    def adjust_parameters(self):
        if len(self.success_history) > 50:
            success_rate = np.mean(self.success_history[-50:])
            if success_rate > 0.3:
                self.de_rate = min(self.de_rate * 1.05, 0.9)  # Increase DE rate if doing well
            else:
                self.de_rate = max(self.de_rate * 0.95, 0.1)  # Decrease DE rate if not

            if success_rate < 0.1:
                self.ls_radius = min(self.ls_radius * 1.1, 1.0)
            else:
                self.ls_radius = max(self.ls_radius * 0.9, 0.001)


    def __call__(self, func):
        self.initialize_population(func)

        while self.eval_count < self.budget:
            self.differential_evolution(func)
            self.local_search(func)
            self.adjust_parameters()

        return self.f_opt, self.x_opt

import numpy as np

class AdaptiveGradientOptimization:
    def __init__(self, budget=10000, dim=10, step_size=0.1):
        self.budget = budget
        self.dim = dim
        self.step_size = step_size

    def estimate_gradient(self, func, x, epsilon=1e-5):
        grad_est = np.zeros(self.dim)
        for i in range(self.dim):
            delta = np.zeros_like(x)
            delta[i] = epsilon
            grad_est[i] = (func(x + delta) - func(x - delta)) / (2 * epsilon)
        return grad_est

    def __call__(self, func):
        lb, ub = np.full(self.dim, -5.0), np.full(self.dim, 5.0)
        x = np.random.uniform(lb, ub)
        f_opt = func(x)
        x_opt = x

        for _ in range(self.budget - 1):
            grad_est = self.estimate_gradient(func, x)
            if np.linalg.norm(grad_est) > 1e-5:
                new_x = np.clip(x - self.step_size * grad_est, lb, ub)
                new_f = func(new_x)
                if new_f < f_opt:
                    f_opt = new_f
                    x_opt = new_x
            else:
                new_x = np.random.uniform(lb, ub)
                new_f = func(new_x)
                if new_f < f_opt:
                    f_opt = new_f
                    x_opt = new_x

        return f_opt, x_opt

import numpy as np

class ChaoticDynamicsOptimizer:
    def __init__(self, budget=10000, dim=10, r=3.9):
        self.budget = budget
        self.dim = dim
        self.r = r  # Control parameter for logistic map
        self.x0 = np.random.uniform(-5.0, 5.0, dim)  # Initial state

    def logistic_map(self, x):
        return self.r * x * (1 - x)

    def generate_new_solution(self, current_solution):
        chaotic_sequence = np.array([self.logistic_map(x) for x in current_solution])
        new_solution = -5.0 + 10.0 * chaotic_sequence  # Scale to [-5, 5]
        return new_solution

    def __call__(self, func):
        self.f_opt = np.inf
        self.x_opt = None

        current_solution = self.x0.copy()
        for i in range(self.budget):
            f = func(current_solution)
            if f < self.f_opt:
                self.f_opt = f
                self.x_opt = current_solution

            # Generate a new candidate solution based on chaotic dynamics
            current_solution = self.generate_new_solution(current_solution)

        return self.f_opt, self.x_opt

import numpy as np

class HybridOptimizationAlgorithm:
    def __init__(self, budget=10000, dim=10, alpha=0.5, beta=0.2):
        self.budget = budget
        self.dim = dim
        self.alpha = alpha  # Exploration rate
        self.beta = beta    # Local search step size

    def __call__(self, func):
        lb, ub = -5.0, 5.0
        x_current = np.random.uniform(lb, ub, self.dim)
        f_current = func(x_current)

        for _ in range(self.budget - 1):
            # Exploration: Move to a new random point with probability alpha
            if np.random.rand() < self.alpha:
                x_new = np.random.uniform(lb, ub, self.dim)
            else:
                # Exploitation: Perform local search around the current best solution
                x_new = np.clip(x_current + self.beta * np.random.randn(self.dim), lb, ub)

            f_new = func(x_new)

            if f_new < f_current:
                f_current = f_new
                x_current = x_new

        return f_current, x_current

