import numpy as np

class AdaptiveLocalSearch:
    def __init__(self, budget=10000, dim=10, step_size=0.1):
        self.budget = budget
        self.dim = dim
        self.step_size = step_size
        self.bounds = np.array([[-5.0] * dim, [5.0] * dim])

    def __call__(self, func):
        best_f = np.inf
        best_x = np.random.uniform(*self.bounds)

        for _ in range(self.budget):
            # Generate a candidate solution using step size
            candidate_x = best_x + np.random.normal(0, self.step_size, self.dim).clip(*self.bounds)

            candidate_f = func(candidate_x)

            if candidate_f < best_f:
                best_f = candidate_f
                best_x = candidate_x

            # Update the step size based on performance
            if candidate_f >= best_f:
                self.step_size *= 0.95
            else:
                self.step_size *= 1.1

        return best_f, best_x

