import numpy as np

class AdaptiveGridSearch:
    def __init__(self, budget=10000, dim=10):
        self.budget = budget
        self.dim = dim
        self.grid_size = int(np.ceil((self.budget/self.dim)**(1/self.dim)))
        self.lb = -5.0
        self.ub = 5.0

    def __call__(self, func):
        grid = np.linspace(self.lb, self.ub, self.grid_size)
        f_min = np.inf
        x_opt = None

        for _ in range(self.budget):
            if _ % self.dim == 0:
                indices = [np.random.randint(len(grid)) for _ in range(self.dim)]
                x = np.array([grid[i] for i in indices])
            else:
                dim_to_update = _ % self.dim
                current_best_index = indices[dim_to_update]
                if current_best_index == len(grid) - 1 or x[dim_to_update] >= grid[current_best_index + 1]:
                    new_index = current_best_index - 1
                elif current_best_index == 0 or x[dim_to_update] <= grid[current_best_index - 1]:
                    new_index = current_best_index + 1
                else:
                    if np.random.rand() < 0.5:
                        new_index = current_best_index - 1
                    else:
                        new_index = current_best_index + 1
                indices[dim_to_update] = new_index
                x[dim_to_update] = grid[new_index]
            f = func(x)
            if f < f_min:
                f_min = f
                x_opt = x.copy()
        return f_min, x_opt

