class NovelHeuristicOptimizer:
    def __init__(self, budget=10000, dim=10, pop_size=50):
        self.budget = budget
        self.dim = dim
        self.pop_size = pop_size
        self.bounds = (-5.0, 5.0)

    def _initialize_population(self):
        return np.random.uniform(self.bounds[0], self.bounds[1], (self.pop_size, self.dim))

    def _mutate(self, individual, population):
        idxs = np.random.choice(len(population), 3, replace=False)
        mutant = population[idxs].mean(axis=0) + 0.5 * (population[idxs][0] - population[idxs][1])
        return np.clip(mutant, self.bounds[0], self.bounds[1])

    def _crossover(self, individual, mutant):
        crossover_mask = np.random.rand(self.dim) < 0.7
        trial = np.where(crossover_mask, mutant, individual)
        return trial

    def __call__(self, func):
        population = self._initialize_population()
        evaluations = 0

        for _ in range(self.budget // self.pop_size):
            if evaluations >= self.budget:
                break

            new_population = []
            for i in range(len(population)):
                mutant = self._mutate(population[i], population)
                trial = self._crossover(population[i], mutant)

                f_trial = func(trial)
                f_pop = func(population[i])

                evaluations += 2

                if f_trial < f_pop:
                    new_population.append(trial)
                else:
                    new_population.append(population[i])

            population = np.array(new_population)

        best_idx = np.argmin(func(population))
        return func(population[best_idx]), population[best_idx]

