class RefinedAdaptiveDirectionalSampling:
    def __init__(self, budget=10000, dim=10, initial_step_size=1.0, decay_rate=0.95, exploration_rate=0.2):
        self.budget = budget
        self.dim = dim
        self.step_size = initial_step_size
        self.decay_rate = decay_rate
        self.exploration_rate = exploration_rate
        self.best_x = None
        self.best_f = np.inf
        self.successful_directions = []

    def __call__(self, func):
        self.best_x = np.random.uniform(func.bounds.lb, func.bounds.ub, self.dim)
        self.best_f = func(self.best_x)

        for i in range(self.budget -1):
            if np.random.rand() < self.exploration_rate:
                x = np.random.uniform(func.bounds.lb, func.bounds.ub, self.dim)
            else:
                if not self.successful_directions:
                    x = np.random.uniform(func.bounds.lb, func.bounds.ub, self.dim)
                else:
                    avg_direction = np.mean(self.successful_directions, axis=0)
                    avg_direction /= np.linalg.norm(avg_direction)
                    x = np.clip(self.best_x + self.step_size * avg_direction, func.bounds.lb, func.bounds.ub)

            f = func(x)
            if f < self.best_f:
                self.best_f = f
                self.best_x = x
                self.step_size *= 1.2
                self.successful_directions.append(x - self.best_x)
            else:
                self.step_size *= self.decay_rate

        return self.best_f, self.best_x

import numpy as np

class DifferentialEvolutionOptimizer:
    def __init__(self, budget=10000, dim=10, pop_size=50, cross_prob=0.8, mutation_rate=0.5):
        self.budget = budget
        self.dim = dim
        self.pop_size = pop_size
        self.cross_prob = cross_prob
        self.mutation_rate = mutation_rate

    def __call__(self, func):
        population = np.random.uniform(-5.0, 5.0, (self.pop_size, self.dim))
        fitness = [func(individual) for individual in population]
        best_index = np.argmin(fitness)
        best_solution = population[best_index]

        for _ in range(self.budget):
            for i in range(self.pop_size):
                mutant = self._mutate(population, i)
                trial = self._crossover(population[i], mutant)
                trial_fitness = func(trial)

                if trial_fitness < fitness[i]:
                    population[i] = trial
                    fitness[i] = trial_fitness
                    if trial_fitness < fitness[best_index]:
                        best_index = i
                        best_solution = trial
        return fitness[best_index], best_solution

    def _mutate(self, population, target):
        indices = np.random.choice(range(self.pop_size), 3, replace=False)
        a, b, c = population[indices]
        return a + self.mutation_rate * (b - c)

    def _crossover(self, current, mutant):
        trial = np.copy(current)
        for i in range(self.dim):
            if np.random.rand() < self.cross_prob:
                trial[i] = mutant[i]
        return np.clip(trial, -5.0, 5.0)

import numpy as np

class DifferentialEvolutionOptimizer:
    def __init__(self, budget=10000, dim=10, population_size=50, mutation_rate=0.8, crossover_rate=0.7):
        self.budget = budget
        self.dim = dim
        self.population_size = population_size
        self.mutation_rate = mutation_rate
        self.crossover_rate = crossover_rate

    def __call__(self, func):
        population = np.random.uniform(-5.0, 5.0, (self.population_size, self.dim))
        fitness = np.array([func(individual) for individual in population])
        best_idx = np.argmin(fitness)

        for _ in range(self.budget):
            new_population = []
            for i in range(self.population_size):
                mutant = self._mutate(population, i)
                trial = self._crossover(population[i], mutant)
                trial_fitness = func(trial)

                if trial_fitness < fitness[i]:
                    new_population.append(trial)
                    fitness[i] = trial_fitness
                    if trial_fitness < fitness[best_idx]:
                        best_idx = i
                else:
                    new_population.append(population[i])
            population = np.array(new_population)
        return fitness[best_idx], population[best_idx]

    def _mutate(self, population, target):
        a, b, c = np.random.choice(range(len(population)), 3, replace=False)
        mutant = population[a] + self.mutation_rate * (population[b] - population[c])
        mutant = np.clip(mutant, -5.0, 5.0)
        return mutant

    def _crossover(self, individual1, individual2):
        trial = []
        for i in range(len(individual1)):
            if np.random.rand() < self.crossover_rate:
                trial.append(individual2[i])
            else:
                trial.append(individual1[i])
        return np.array(trial)

