class AdaptiveDE:
    def __init__(self, budget=10000, dim=10, pop_size=40, F=0.5, CR=0.9):
        self.budget = budget
        self.dim = dim
        self.pop_size = pop_size
        self.F = F  # Mutation factor
        self.CR = CR  # Crossover rate
        self.archive_size = int(self.pop_size * 0.1)
        self.archive = []

    def __call__(self, func):
        self.f_opt = np.Inf
        self.x_opt = None
        self.population = np.random.uniform(func.bounds.lb, func.bounds.ub, size=(self.pop_size, self.dim))
        self.fitness = np.array([func(x) for x in self.population])
        self.budget -= self.pop_size

        if np.min(self.fitness) < self.f_opt:
            self.f_opt = np.min(self.fitness)
            self.x_opt = self.population[np.argmin(self.fitness)]

        while self.budget > 0:
            for i in range(self.pop_size):
                # Mutation
                idxs = np.random.choice(self.pop_size + len(self.archive), 3, replace=False)

                # Select from population or archive
                if idxs[0] < self.pop_size:
                    x_r1 = self.population[idxs[0]]
                else:
                    x_r1 = self.archive[idxs[0] - self.pop_size]

                if idxs[1] < self.pop_size:
                    x_r2 = self.population[idxs[1]]
                else:
                    x_r2 = self.archive[idxs[1] - self.pop_size]

                if idxs[2] < self.pop_size:
                    x_r3 = self.population[idxs[2]]
                else:
                    x_r3 = self.archive[idxs[2] - self.pop_size]

                v = x_r1 + self.F * (x_r2 - x_r3)
                v = np.clip(v, func.bounds.lb, func.bounds.ub)  # Keep within bounds

                # Crossover
                j_rand = np.random.randint(self.dim)
                u = np.copy(self.population[i])
                for j in range(self.dim):
                    if np.random.rand() < self.CR or j == j_rand:
                        u[j] = v[j]

                # Selection
                f = func(u)
                self.budget -= 1
                if self.budget <= 0:
                    break

                if f < self.fitness[i]:
                    self.population[i] = u
                    self.fitness[i] = f

                    # Update archive using the current population
                    if len(self.archive) < self.archive_size:
                        self.archive.append(u)
                    else:
                        idx_worst = np.argmax(self.fitness) #replace worst in pop
                        if f < self.fitness[idx_worst]:
                             idx_archive = np.random.randint(self.archive_size) #replace random in archive
                             self.archive[idx_archive] = u # replace in archive

                if f < self.f_opt:
                    self.f_opt = f
                    self.x_opt = u

        return self.f_opt, self.x_opt

import numpy as np

class AdaptiveDE:
    def __init__(self, budget=10000, dim=10, pop_size=40, CR=0.9):
        self.budget = budget
        self.dim = dim
        self.pop_size = pop_size
        self.CR = CR  # Crossover rate
        self.archive_size = int(self.pop_size * 0.1)
        self.archive = []

    def __call__(self, func):
        self.f_opt = np.Inf
        self.x_opt = None
        self.population = np.random.uniform(func.bounds.lb, func.bounds.ub, size=(self.pop_size, self.dim))
        self.fitness = np.array([func(x) for x in self.population])
        self.budget -= self.pop_size

        if np.min(self.fitness) < self.f_opt:
            self.f_opt = np.min(self.fitness)
            self.x_opt = self.population[np.argmin(self.fitness)]

        while self.budget > 0:
            for i in range(self.pop_size):
                # Mutation with adaptive F
                F = np.random.uniform(0.4, 0.9)  # Self-adaptive mutation factor
                idxs = np.random.choice(self.pop_size + len(self.archive), 3, replace=False)

                # Select from population or archive
                if idxs[0] < self.pop_size:
                    x_r1 = self.population[idxs[0]]
                else:
                    x_r1 = self.archive[idxs[0] - self.pop_size]

                if idxs[1] < self.pop_size:
                    x_r2 = self.population[idxs[1]]
                else:
                    x_r2 = self.archive[idxs[1] - self.pop_size]

                if idxs[2] < self.pop_size:
                    x_r3 = self.population[idxs[2]]
                else:
                    x_r3 = self.archive[idxs[2] - self.pop_size]

                v = x_r1 + F * (x_r2 - x_r3)
                v = np.clip(v, func.bounds.lb, func.bounds.ub)  # Keep within bounds

                # Crossover
                j_rand = np.random.randint(self.dim)
                u = np.copy(self.population[i])
                for j in range(self.dim):
                    if np.random.rand() < self.CR or j == j_rand:
                        u[j] = v[j]

                # Selection
                f = func(u)
                self.budget -= 1
                if self.budget <= 0:
                    break

                if f < self.fitness[i]:
                    self.population[i] = u
                    self.fitness[i] = f

                    # Update archive using the current population
                    if len(self.archive) < self.archive_size:
                        self.archive.append(u)
                    else:
                        idx_worst = np.argmax(self.fitness)
                        if f < self.fitness[idx_worst]:
                            idx_archive = np.random.randint(self.archive_size)
                            self.archive[idx_archive] = u

                if f < self.f_opt:
                    self.f_opt = f
                    self.x_opt = u

        return self.f_opt, self.x_opt

import numpy as np

class SimplifiedPSO:
    def __init__(self, budget=10000, dim=10, num_particles=50):
        self.budget = budget
        self.dim = dim
        self.num_particles = num_particles

    def __call__(self, func):
        particles = np.random.uniform(func.bounds.lb, func.bounds.ub, (self.num_particles, self.dim))
        velocities = np.zeros((self.num_particles, self.dim))
        pbest_positions = particles.copy()
        gbest_position = pbest_positions[np.argmin([func(p) for p in particles])]

        for _ in range(self.budget):
            r1, r2 = np.random.rand(), np.random.rand()
            velocities = 0.7 * velocities + r1 * (pbest_positions - particles) + r2 * (gbest_position - particles)
            particles += velocities
            particles = np.clip(particles, func.bounds.lb, func.bounds.ub)

            for i in range(self.num_particles):
                if func(particles[i]) < func(pbest_positions[i]):
                    pbest_positions[i] = particles[i]
                if func(particles[i]) < func(gbest_position):
                    gbest_position = particles[i]

        return func(gbest_position), gbest_position

import numpy as np

class AdaptiveGaussianSearch:
    def __init__(self, budget=10000, dim=10, initial_sigma=1.0, decay_rate=0.95, exploration_rate=0.2):
        self.budget = budget
        self.dim = dim
        self.sigma = initial_sigma
        self.decay_rate = decay_rate
        self.exploration_rate = exploration_rate
        self.f_opt = np.inf
        self.x_opt = np.random.uniform(-5, 5, dim)

    def __call__(self, func):
        for i in range(self.budget):
            if np.random.rand() < self.exploration_rate:
                x = np.random.uniform(func.bounds.lb, func.bounds.ub)
            else:
                x = self.x_opt + np.random.normal(0, self.sigma, self.dim)
                x = np.clip(x, func.bounds.lb, func.bounds.ub)

            f = func(x)
            if f < self.f_opt:
                self.f_opt = f
                self.x_opt = x
                self.sigma *= 1.1  # Increase sigma upon success
            else:
                self.sigma *= self.decay_rate
                self.sigma = max(self.sigma, 0.01) #Avoid stagnation

        return self.f_opt, self.x_opt

