import numpy as np

class AdaptiveLocalSearch:
    def __init__(self, budget=10000, dim=10):
        self.budget = budget
        self.dim = dim
        self.step_size = np.full(dim, 1.0)

    def local_search(self, func, x):
        f_best = func(x)
        for i in range(self.dim):
            x_new = x.copy()
            for delta in [-self.step_size[i], self.step_size[i]]:
                x_new[i] += delta
                if 0 <= x_new[i] <= 5.0:
                    f_new = func(x_new)
                    if f_new < f_best:
                        f_best = f_new
                        x[:] = x_new[:]
        return f_best

    def __call__(self, func):
        self.f_opt = np.Inf
        self.x_opt = np.random.uniform(-5.0, 5.0, self.dim)

        for i in range(self.budget):
            f_current = func(self.x_opt)
            if f_current < self.f_opt:
                self.f_opt = f_current

            f_best = self.local_search(func, self.x_opt)

            # Adaptive step size adjustment
            if f_best == self.f_opt:
                self.step_size *= 0.9
            else:
                self.step_size *= 1.1

        return self.f_opt, self.x_opt

