import numpy as np

class HybridSearch:
    def __init__(self, budget=10000, dim=10, step_size=0.1):
        self.budget = budget
        self.dim = dim
        self.step_size = step_size

    def __call__(self, func):
        self.f_opt = np.Inf
        self.x_opt = None

        # Initial random search to find a promising starting point
        for _ in range(self.budget // 2):
            x = np.random.uniform(func.bounds.lb, func.bounds.ub)
            f = func(x)
            if f < self.f_opt:
                self.f_opt = f
                self.x_opt = x

        # Hill climbing from the best found point
        for _ in range(self.budget // 2):
            if self.x_opt is None:
                break

            for d in range(self.dim):
                # Try moving up in dimension d
                new_x = np.copy(self.x_opt)
                new_x[d] += self.step_size
                if new_x[d] > func.bounds.ub[d]:
                    new_x[d] = func.bounds.ub[d]
                f_new = func(new_x)

                if f_new < self.f_opt:
                    self.f_opt = f_new
                    self.x_opt = new_x

                # Try moving down in dimension d
                new_x[d] -= 2 * self.step_size
                if new_x[d] < func.bounds.lb[d]:
                    new_x[d] = func.bounds.lb[d]
                f_new = func(new_x)

                if f_new < self.f_opt:
                    self.f_opt = f_new
                    self.x_opt = new_x

        return self.f_opt, self.x_opt

