class RefinedSimplifiedAdaptiveDifferentialEvolution:
    def __init__(self, budget=10000, dim=10):
        self.budget = budget
        self.dim = dim
        self.population_size = 2 * dim
        self.mutation_rate = 0.7
        self.crossover_rate = 0.9

    def __call__(self, func):
        lb, ub = -5.0, 5.0
        population = np.random.uniform(lb, ub, (self.population_size, self.dim))
        fitness = np.array([func(ind) for ind in population])

        for _ in range(self.budget - self.population_size):
            for i in range(self.population_size):
                a, b, c = np.random.choice(np.delete(np.arange(self.population_size), i), 3, replace=False)
                mutant = population[a] + self.mutation_rate * (population[b] - population[c])
                mutant = np.clip(mutant, lb, ub)

                trial = population[i].copy()
                for j in range(self.dim):
                    if np.random.rand() < self.crossover_rate:
                        trial[j] = mutant[j]

                trial_fitness = func(trial)
                if trial_fitness < fitness[i]:
                    population[i] = trial
                    fitness[i] = trial_fitness

                    # Adaptive mutation rate based on improvement
                    if trial_fitness < fitness.min():
                        self.mutation_rate += 0.1 * np.clip(np.random.randn(), -0.5, 0.5)

        best_idx = np.argmin(fitness)
        return fitness[best_idx], population[best_idx]

