class RefinedAdaptiveGaussianSearchImproved:
    def __init__(self, budget=10000, dim=10, initial_std=1.0, decay_rate=0.95, exploration_rate=0.2):
        self.budget = budget
        self.dim = dim
        self.initial_std = initial_std
        self.decay_rate = decay_rate
        self.exploration_rate = exploration_rate

    def __call__(self, func):
        self.best_solution = np.random.uniform(func.bounds.lb, func.bounds.ub, self.dim)
        self.best_fitness = func(self.best_solution)

        for i in range(self.budget -1):
            std = self.initial_std * (self.decay_rate** (i / self.budget))  #Simplified decay

            if np.random.rand() < self.exploration_rate:
                x = np.random.uniform(func.bounds.lb, func.bounds.ub, self.dim)
            else:
                x = np.random.normal(loc=self.best_solution, scale=std, size=self.dim)
                x = np.clip(x, func.bounds.lb, func.bounds.ub)

            fitness = func(x)
            if fitness < self.best_fitness:
                self.best_fitness = fitness
                self.best_solution = x

        return self.best_fitness, self.best_solution

import numpy as np

class EnhancedPSO:
    def __init__(self, budget=10000, dim=10, num_particles=30):
        self.budget = budget
        self.dim = dim
        self.num_particles = num_particles
        self.bounds = np.array([[-5.0] * dim, [5.0] * dim])

    def local_search(self, func, x):
        step_size = 0.1
        for _ in range(int(self.budget / self.num_particles)):
            new_x = np.clip(x + np.random.uniform(-step_size, step_size), -5.0, 5.0)
            if func(new_x) < func(x):
                x = new_x
        return x

    def __call__(self, func):
        particles = np.random.uniform(-5.0, 5.0, (self.num_particles, self.dim))
        personal_bests = particles
        global_best = min(personal_bests, key=func)

        for _ in range(int(self.budget / self.num_particles)):
            r1, r2 = np.random.rand(2)
            particles += (r1 * (personal_bests - particles)) + (r2 * (global_best - particles))
            particles = np.clip(particles, -5.0, 5.0)
            for i in range(self.num_particles):
                if func(particles[i]) < func(personal_bests[i]):
                    personal_bests[i] = particles[i]
                    if func(particles[i]) < func(global_best):
                        global_best = particles[i]
            global_best = self.local_search(func, global_best)

        return func(global_best), global_best

