class AdaptiveMutationLocalSearch:
    def __init__(self, budget=10000, dim=10, mutation_rate=0.1):
        self.budget = budget
        self.dim = dim
        self.mutation_rate = mutation_rate
        self.bounds = (-5.0, 5.0)

    def mutate(self, x, rate):
        mutated_x = np.copy(x)
        for i in range(len(mutated_x)):
            if np.random.rand() < rate:
                mutated_x[i] += np.random.normal(0, 1) * (self.bounds[1] - self.bounds[0]) / 10
                mutated_x[i] = np.clip(mutated_x[i], self.bounds[0], self.bounds[1])
        return mutated_x

    def local_search(self, func, x):
        step_size = 0.1
        for _ in range(10):  # Local search steps
            neighbor = x + np.random.uniform(-step_size, step_size, size=self.dim)
            neighbor = np.clip(neighbor, self.bounds[0], self.bounds[1])
            if func(neighbor) < func(x):
                x = neighbor
        return x

    def __call__(self, func):
        self.f_opt = np.Inf
        self.x_opt = np.random.uniform(self.bounds[0], self.bounds[1], size=self.dim)

        for _ in range(self.budget):
            mutated_x = self.mutate(self.x_opt, self.mutation_rate)
            improved_x = self.local_search(func, mutated_x)

            f = func(improved_x)
            if f < self.f_opt:
                self.f_opt = f
                self.x_opt = improved_x

        return self.f_opt, self.x_opt

