class RefinedAdaptiveVarianceGuidedRandomSearch:
    def __init__(self, budget=10000, dim=10, initial_variance=1.0, decay_rate=0.98):
        self.budget = budget
        self.dim = dim
        self.variance = initial_variance * np.ones(dim)
        self.best_solution = None
        self.best_fitness = float('inf')
        self.lower_bounds = -5.0 * np.ones(dim)
        self.upper_bounds = 5.0 * np.ones(dim)
        self.decay_rate = decay_rate

    def __call__(self, func):
        for i in range(self.budget):
            if self.best_solution is None:
                x = np.random.uniform(self.lower_bounds, self.upper_bounds)
            else:
                x = np.clip(np.random.normal(self.best_solution, self.variance), self.lower_bounds, self.upper_bounds)

            fitness = func(x)

            if fitness < self.best_fitness:
                self.best_fitness = fitness
                self.best_solution = x
                self.variance *= 1.02 #Slight increase after improvement
            else:
                self.variance *= self.decay_rate #Decay variance gradually

        return self.best_fitness, self.best_solution

