        self.best_fitness = float('inf')
        self.lower_bounds = -5.0 * np.ones(dim)
        self.upper_bounds = 5.0 * np.ones(dim)
        self.variance_decay = variance_decay

    def __call__(self, func):
        for i in range(self.budget):
            if self.best_solution is None:
                x = np.random.uniform(self.lower_bounds, self.upper_bounds)
            else:
                exploration_rate = 1.0 - i / self.budget  # Linear decay of exploration
                x = np.random.normal(self.best_solution, self.variance * exploration_rate)
                x = np.clip(x, self.lower_bounds, self.upper_bounds)

            fitness = func(x)

            if fitness < self.best_fitness:
                self.best_fitness = fitness
                self.best_solution = x
            else:
                self.variance *= self.variance_decay

        return self.best_fitness, self.best_solution

