class EnhancedRandomSearch:
    def __init__(self, budget=10000, dim=10, alpha=0.5):
        self.budget = budget
        self.dim = dim
        self.alpha = alpha  # Probability of local exploitation

    def __call__(self, func):
        lb, ub = -5.0, 5.0
        self.f_opt = np.Inf
        self.x_opt = np.random.uniform(lb, ub, size=self.dim)

        for i in range(1, self.budget + 1):
            if np.random.rand() < self.alpha:
                # Local exploitation: Perturb the current best solution
                x_new = np.clip(self.x_opt + np.random.normal(0, 0.1, size=self.dim), lb, ub)
            else:
                # Exploration: Random search in the entire space
                x_new = np.random.uniform(lb, ub, size=self.dim)

            f_new = func(x_new)
            if f_new < self.f_opt:
                self.f_opt = f_new
                self.x_opt = x_new

        return self.f_opt, self.x_opt

