import numpy as np

class HybridDEGM:
    def __init__(self, budget=10000, dim=10):
        self.budget = budget
        self.dim = dim
        self.population_size = 30
        self.mutation_factor = 0.8
        self.crossover_rate = 0.9

    def initialize_population(self, lb, ub):
        return np.random.uniform(lb, ub, (self.population_size, self.dim))

    def mutate(self, x, y, z, F, lb, ub):
        mutant = np.zeros_like(x)
        for i in range(len(x)):
            if np.random.rand() < F or i == np.random.randint(0, len(x)):
                mutant[i] = y[i] + F * (z[i] - x[i])
            else:
                mutant[i] = x[i]
        return np.clip(mutant, lb, ub)

    def crossover(self, target, donor, CR):
        trial = np.zeros_like(target)
        jrand = np.random.randint(0, self.dim)
        for i in range(len(target)):
            if np.random.rand() < CR or i == jrand:
                trial[i] = donor[i]
            else:
                trial[i] = target[i]
        return trial

    def __call__(self, func):
        lb, ub = -5.0, 5.0
        population = self.initialize_population(lb, ub)
        fitness = np.array([func(x) for x in population])

        best_idx = np.argmin(fitness)
        f_opt, x_opt = fitness[best_idx], population[best_idx]

        iteration = 0
        while iteration < self.budget:
            for i in range(self.population_size):
                a, b, c = np.random.choice(np.arange(self.population_size), 3, replace=False)
                mutant = self.mutate(population[a], population[b], population[c], self.mutation_factor, lb, ub)

                # Gaussian Mutation
                gaussian_mutation = np.random.normal(0, 0.1, self.dim)
                mutated_trial = mutant + gaussian_mutation * (ub - lb) / 2

                trial = self.crossover(population[i], mutated_trial, self.crossover_rate)

                f_trial = func(trial)
                if f_trial < fitness[i]:
                    population[i] = trial
                    fitness[i] = f_trial
                    if f_trial < f_opt:
                        f_opt = f_trial
                        x_opt = trial

            iteration += self.population_size

        return f_opt, x_opt

