class ImprovedAdaptiveParticleSwarmOptimization:
    def __init__(self, budget=10000, dim=10, num_particles=50, w_min=0.4, w_max=0.9, c1=2.0, c2=2.0):
        self.budget = budget
        self.dim = dim
        self.num_particles = num_particles
        self.w_min, self.w_max, self.c1, self.c2 = w_min, w_max, c1, c2

    def __call__(self, func):
        particles = np.random.uniform(func.bounds.lb, func.bounds.ub, (self.num_particles, self.dim))
        velocities = np.zeros((self.num_particles, self.dim))
        pbest_positions = particles.copy()
        gbest_position = particles[np.argmin([func(p) for p in particles])]

        for iteration in range(self.budget):
            r1, r2 = np.random.rand(2)
            w = self.w_max - (iteration / self.budget) * (self.w_max - self.w_min)  # Adaptive inertia weight
            velocities = w * velocities + self.c1 * r1 * (pbest_positions - particles) + self.c2 * r2 * (gbest_position - particles)
            particles += velocities

            for i in range(self.num_particles):
                if func(particles[i]) < func(pbest_positions[i]):
                    pbest_positions[i] = particles[i].copy()
                    if func(pbest_positions[i]) < func(gbest_position):
                        gbest_position = pbest_positions[i].copy()
        return func(gbest_position), gbest_position

