class AdaptiveCoordinateDescent:
    def __init__(self, budget=10000, dim=10, initial_step_size=1.0, success_window=10):
        self.budget = budget
        self.dim = dim
        self.step_size = initial_step_size
        self.success_history = []
        self.success_window = success_window

    def __call__(self, func):
        x_opt = np.random.uniform(func.bounds.lb, func.bounds.ub)
        f_opt = func(x_opt)
        evals = 1

        while evals < self.budget:
            for i in range(self.dim):
                # Explore both directions
                for direction in [-1, 1]:
                    x_new = x_opt.copy()
                    x_new[i] += self.step_size * direction
                    x_new[i] = np.clip(x_new[i], func.bounds.lb[i], func.bounds.ub[i])

                    f_new = func(x_new)
                    evals += 1

                    if f_new < f_opt:
                        f_opt = f_new
                        x_opt = x_new
                        self.success_history.append(1)
                    else:
                        self.success_history.append(0)

                    if evals >= self.budget:
                        break
                if evals >= self.budget:
                    break    
            # Update step size based on recent success
            if len(self.success_history) > self.success_window:
                success_rate = np.mean(self.success_history[-self.success_window:])
                if success_rate > 0.6:
                    self.step_size *= 1.1
                elif success_rate < 0.4:
                    self.step_size *= 0.9
                self.step_size = np.clip(self.step_size, 1e-6, 1.0) #keep step size in reasonable range
        return f_opt, x_opt

