class AdaptiveVarianceReductionGuidedSearchImproved:
    def __init__(self, budget=10000, dim=10, initial_variance=1.0, reduction_factor=0.9, exploration_rate=0.1):
        self.budget = budget
        self.dim = dim
        self.initial_variance = initial_variance
        self.reduction_factor = reduction_factor
        self.exploration_rate = exploration_rate
        self.variance = initial_variance
        self.best_solution = None
        self.best_fitness = float('inf')

    def __call__(self, func):
        lb = func.bounds.lb
        ub = func.bounds.ub
        for i in range(self.budget):
            if self.best_solution is None:
                x = np.random.uniform(lb, ub)
            else:
                if np.random.rand() < self.exploration_rate:
                    x = np.random.uniform(lb, ub)
                else:
                    x = np.clip(np.random.normal(self.best_solution, self.variance), lb, ub)
            fitness = func(x)
            if fitness < self.best_fitness:
                self.best_fitness = fitness
                self.best_solution = x
                # Reduce variance only after a successful step to avoid premature convergence.
                self.variance *= self.reduction_factor

        return self.best_fitness, self.best_solution

