class CoordinateSearch:
    def __init__(self, budget=10000, dim=10, init_step_size=0.5):
        self.budget = budget
        self.dim = dim
        self.init_step_size = init_step_size

    def __call__(self, func):
        x = np.random.uniform(func.bounds.lb, func.bounds.ub)
        f_opt = func(x)
        x_opt = x
        step_size = self.init_step_size

        for _ in range(self.budget):
            for i in range(self.dim):
                x[i] += step_size
                f = func(x)
                if f < f_opt:
                    f_opt = f
                    x_opt = np.copy(x)
                else:
                    x[i] -= 2 * step_size
                    f = func(x)
                    if f < f_opt:
                        f_opt = f
                        x_opt = np.copy(x)
                    else:
                        x[i] += step_size
            step_size *= 0.95 # Adaptive Step Size Decay
        return f_opt, x_opt

