class DifferentialEvolutionOptimizer:
    def __init__(self, budget=10000, dim=10, mutation_factor=0.5, crossover_probability=0.7):
        self.budget = budget
        self.dim = dim
        self.mutation_factor = mutation_factor
        self.crossover_probability = crossover_probability
        self.population_size = 2 * dim
        self.bounds = np.array([-5.0, 5.0])
        self.population = np.random.uniform(low=self.bounds[0], high=self.bounds[1], size=(self.population_size, self.dim))

    def mutate(self, target_index):
        indices = list(range(self.population_size))
        indices.remove(target_index)
        a, b, c = np.random.choice(indices, size=3, replace=False)
        return self.population[a] + self.mutation_factor * (self.population[b] - self.population[c])

    def cross_over(self, target_index, mutant):
        trial = np.copy(self.population[target_index])
        for j in range(self.dim):
            if np.random.rand() < self.crossover_probability:
                trial[j] = mutant[j]
        return trial

    def __call__(self, func):
        self.f_opt = np.Inf
        self.x_opt = None

        for i in range(self.budget):
            for j in range(self.population_size):
                mutant = self.mutate(j)
                mutant = np.clip(mutant, a_min=self.bounds[0], a_max=self.bounds[1])
                trial = self.cross_over(j, mutant)

                f_trial = func(trial)
                if f_trial < self.f_opt:
                    self.f_opt = f_trial
                    self.x_opt = trial

        return self.f_opt, self.x_opt

