class EnhancedDifferentialEvolutionOptimizer:
    def __init__(self, budget=10000, dim=10, mutation_factor=0.5, crossover_probability=0.7):
        self.budget = budget
        self.dim = dim
        self.mutation_factor = mutation_factor
        self.crossover_probability = crossover_probability
        self.population_size = 3 * dim
        self.bounds = np.array([-5.0, 5.0])
        self.population = np.random.uniform(low=self.bounds[0], high=self.bounds[1], size=(self.population_size, self.dim))

    def mutate(self, target):
        a, b, c = np.random.choice(self.population_size, 3, replace=False)
        return self.population[a] + self.mutation_factor * (self.population[b] - self.population[c])

    def cross_over(self, target, mutant):
        trial = np.where(np.random.rand(self.dim) < self.crossover_probability, mutant, target)
        return trial

    def __call__(self, func):
        self.f_opt = np.Inf
        self.x_opt = None

        for _ in range(self.budget):
            for i in range(self.population_size):
                mutant = self.mutate(self.population[i])
                trial = self.cross_over(self.population[i], mutant)
                trial = np.clip(trial, *self.bounds)
                f_trial = func(trial)

                if f_trial < self.f_opt:
                    self.f_opt = f_trial
                    self.x_opt = trial
                    self.population[i] = trial
        return self.f_opt, self.x_opt

