class ImprovedDifferentialEvolutionOptimizer:
    def __init__(self, budget=10000, dim=10, F=0.8, CR=0.7):
        self.budget = budget
        self.dim = dim
        self.F = F  # Mutation factor
        self.CR = CR  # Crossover rate
        self.population_size = 10 * dim
        self.bounds = np.array([-5.0, 5.0])
        self.population = np.random.uniform(low=self.bounds[0], high=self.bounds[1], size=(self.population_size, self.dim))

    def mutate_and_crossover(self, target):
        indices = np.arange(self.population_size)
        indices = np.delete(indices, target)
        a, b, c = np.random.choice(indices, size=3, replace=False)
        mutant = self.population[a] + self.F * (self.population[b] - self.population[c])
        trial = np.where(np.random.rand(self.dim) < self.CR, mutant, self.population[target])
        return np.clip(trial, a_min=self.bounds[0], a_max=self.bounds[1])

    def __call__(self, func):
        fitness = np.array([func(individual) for individual in self.population])
        best_idx = np.argmin(fitness)
        for _ in range(self.budget):
            for i in range(self.population_size):
                trial = self.mutate_and_crossover(i)
                trial_fitness = func(trial)
                if trial_fitness < fitness[i]:
                    self.population[i] = trial
                    fitness[i] = trial_fitness
                    if trial_fitness < fitness[best_idx]:
                        best_idx = i
        return fitness[best_idx], self.population[best_idx]

