class SimplifiedAdaptiveDifferentialEvolutionOptimizer:
    def __init__(self, budget=10000, dim=10, mutation_factor_init=0.5, crossover_probability_init=0.7):
        self.budget = budget
        self.dim = dim
        self.mutation_factor_init = mutation_factor_init
        self.crossover_probability_init = crossover_probability_init
        self.population_size = 2 * dim
        self.bounds = np.array([-5.0, 5.0])
        self.population = np.random.uniform(low=self.bounds[0], high=self.bounds[1], size=(self.population_size, self.dim))

    def mutate(self, target, f):
        a, b, c = np.random.choice(self.population_size, 3, replace=False)
        return target + f * (self.population[b] - self.population[c]) + f * (self.population[a] - target)

    def cross_over(self, target, mutant, cr):
        trial = np.where(np.random.rand(self.dim) < cr, mutant, target)
        return trial

    def __call__(self, func):
        self.f_opt = np.Inf
        self.x_opt = None

        for _ in range(self.budget):
            f = self.mutation_factor_init * (1 - (_ / self.budget))
            cr = self.crossover_probability_init * (1 - (_ / self.budget))

            for i in range(self.population_size):
                mutant = self.mutate(self.population[i], f)
                trial = self.cross_over(self.population[i], mutant, cr)
                trial = np.clip(trial, *self.bounds)
                f_trial = func(trial)

                if f_trial < func(self.population[i]):
                    self.population[i] = trial

                if f_trial < self.f_opt:
                    self.f_opt = f_trial
                    self.x_opt = trial
        return self.f_opt, self.x_opt

