    def __init__(self, budget=10000, dim=10, F=0.5, CR=0.7):
        self.budget = budget
        self.dim = dim
        self.F = F  # Mutation factor
        self.CR = CR  # Crossover rate
        self.population_size = 10 * dim
        self.bounds = np.array([-5.0, 5.0])
        self.population = np.random.uniform(low=self.bounds[0], high=self.bounds[1], size=(self.population_size, self.dim))

    def mutate_and_crossover(self, target):
        indices = np.arange(self.population_size)
        a, b = np.random.choice(indices[indices != target], size=2, replace=False)
        mutant = self.population[a] + self.F * (self.population[b] - self.population[target])
        trial = np.where(np.random.rand(self.dim) < self.CR, mutant, self.population[target])
        return np.clip(trial, a_min=self.bounds[0], a_max=self.bounds[1])

    def __call__(self, func):
        fitness = np.array([func(individual) for individual in self.population])
        best_idx = np.argmin(fitness)
        for _ in range(self.budget):
            for i in range(self.population_size):
                trial = self.mutate_and_crossover(i)
                trial_fitness = func(trial)
                if trial_fitness < fitness[i]:
                    self.population[i] = trial
                    fitness[i] = trial_fitness
                    if trial_fitness < fitness[best_idx]:
                        best_idx = i
        return fitness[best_idx], self.population[best_idx]

import numpy as np

class SimplifiedAdaptiveDifferentialEvolutionOptimizer:
    def __init__(self, budget=10000, dim=10, mutation_factor=0.5, crossover_probability=0.7):
        self.budget = budget
        self.dim = dim
        self.mutation_factor = mutation_factor
        self.crossover_probability = crossover_probability
        self.population_size = 10 * dim
        self.bounds = np.array([-5.0, 5.0])
        self.population = np.random.uniform(low=self.bounds[0], high=self.bounds[1], size=(self.population_size, self.dim))

    def mutate(self, target, best):
        a, b, c = np.random.choice(self.population_size, 3, replace=False)
        return best + self.mutation_factor * (self.population[a] - self.population[b]) + self.mutation_factor * (target - self.population[c])

    def cross_over(self, target, mutant):
        trial = np.where(np.random.rand(self.dim) < self.crossover_probability, mutant, target)
        return trial

    def __call__(self, func):
        self.f_opt = np.Inf
        self.x_opt = None
        best_index = 0

        for _ in range(self.budget):
            for i in range(self.population_size):
                mutant = self.mutate(self.population[i], self.population[best_index])
                trial = self.cross_over(self.population[i], mutant)
                trial = np.clip(trial, *self.bounds)
                f_trial = func(trial)

                if f_trial < func(self.population[i]):
                    self.population[i] = trial
                    if f_trial < self.f_opt:
                        self.f_opt = f_trial
                        self.x_opt = trial
                        best_index = i
        return self.f_opt, self.x_opt

