class ImprovedAdaptiveDifferentialEvolutionOptimizer:
    def __init__(self, budget=10000, dim=10):
        self.budget = budget
        self.dim = dim
        self.F = 0.8 * np.ones(dim)  # Mutation factor for each dimension
        self.CR = 0.5 * np.ones(dim)  # Crossover rate for each dimension
        self.population_size = 10 * dim
        self.bounds = np.array([-5.0, 5.0])
        self.population = np.random.uniform(low=self.bounds[0], high=self.bounds[1], size=(self.population_size, self.dim))

    def mutate_and_crossover(self, target):
        best_idx = np.argmin(self.fitness)
        mutant = self.population[best_idx] + self.F * (np.random.uniform() * (self.population[target] - self.population[best_idx]))  # Mutate the best individual
        trial = np.where(np.random.rand(self.dim) < self.CR, mutant, self.population[target])
        return np.clip(trial, a_min=self.bounds[0], a_max=self.bounds[1])

    def __call__(self, func):
        self.fitness = np.array([func(individual) for individual in self.population])
        best_idx = np.argmin(self.fitness)
        for _ in range(self.budget):
            for i in range(self.population_size):
                trial = self.mutate_and_crossover(i)
                trial_fitness = func(trial)
                if trial_fitness < self.fitness[i]:
                    self.population[i] = trial
                    self.fitness[i] = trial_fitness
                    if trial_fitness < self.fitness[best_idx]:
                        best_idx = i
            for j in range(self.dim):  # Self-adaptation of crossover rate for each dimension
                self.CR[j] *= np.random.uniform(0.8, 1.2)
        return self.fitness[best_idx], self.population[best_idx]

import numpy as np

class HybridEA:
    def __init__(self, budget=10000, dim=10, pop_size=50):
        self.budget = budget
        self.dim = dim
        self.pop_size = pop_size
        self.bounds = (-5.0, 5.0)

    def initialize_population(self):
        return np.random.uniform(self.bounds[0], self.bounds[1], (self.pop_size, self.dim))

    def evaluate_population(self, population, func):
        return np.array([func(ind) for ind in population])

    def selection(self, population, fitness):
        sorted_indices = np.argsort(fitness)
        selected_indices = sorted_indices[:int(0.7 * self.pop_size)]
        return population[selected_indices]

    def crossover(self, parents):
        offspring = []
        num_parents = len(parents)
        for i in range(num_parents // 2):
            parent1, parent2 = parents[i], parents[i + (num_parents // 2)]
            alpha = np.random.uniform(0.5, 1.0)
            child1 = alpha * parent1 + (1 - alpha) * parent2
            child2 = alpha * parent2 + (1 - alpha) * parent1
            offspring.extend([child1, child2])
        return np.array(offspring)

    def mutation(self, population):
        mutated_population = []
        for ind in population:
            if np.random.rand() < 0.1:
                mutated_ind = ind + np.random.normal(0, 0.5, self.dim)
                mutated_ind = np.clip(mutated_ind, self.bounds[0], self.bounds[1])
                mutated_population.append(mutated_ind)
            else:
                mutated_population.append(ind)
        return np.array(mutated_population)

    def local_search(self, ind, func):
        step_size = 0.5
        for _ in range(20):
            new_ind = ind + np.random.normal(0, step_size, self.dim)
            new_ind = np.clip(new_ind, self.bounds[0], self.bounds[1])
            if func(new_ind) < func(ind):
                ind = new_ind
        return ind

    def __call__(self, func):
        population = self.initialize_population()
        fitness = self.evaluate_population(population, func)
        evaluations = len(fitness)

        while evaluations + self.pop_size <= self.budget:
            parents = self.selection(population, fitness)
            offspring = self.crossover(parents)
            offspring = self.mutation(offspring)
            for i in range(len(offspring)):
                offspring[i] = self.local_search(offspring[i], func)
                evaluations += 1
            population = np.vstack((parents, offspring))
            fitness = self.evaluate_population(population, func)

        best_idx = np.argmin(fitness)
        return fitness[best_idx], population[best_idx]

