class AdaptiveMutationOptimizer:
    def __init__(self, budget=10000, dim=10):
        self.budget = budget
        self.dim = dim
        self.bounds = (-5.0, 5.0)

    def __call__(self, func):
        x = np.random.uniform(self.bounds[0], self.bounds[1], size=self.dim)
        f_opt = func(x)

        for _ in range(1, self.budget):
            candidate = np.clip(x + np.random.normal(size=self.dim), *self.bounds)
            f_candidate = func(candidate)

            if f_candidate < f_opt:
                x = candidate
                f_opt = f_candidate

        return f_opt, x

