class SimplifiedAdaptiveSearch:
    def __init__(self, budget=10000, dim=10, step_size=0.1):
        self.budget = budget
        self.dim = dim
        self.step_size = step_size
        self.f_opt = np.inf
        self.x_opt = None

    def approximate_gradient(self, func, x):
        grad = np.zeros_like(x)
        for i in range(len(x)):
            x_plus = x.copy()
            x_plus[i] += self.step_size
            grad[i] = (func(x_plus) - func(x)) / self.step_size
        return grad

    def __call__(self, func):
        for _ in range(self.budget):
            if np.random.rand() < 0.5 and self.x_opt is not None:
                # Adaptive step based on gradient
                grad = self.approximate_gradient(func, self.x_opt)
                x_new = self.x_opt - self.step_size * grad / (np.linalg.norm(grad) + 1e-8)
            else:
                # Random exploration
                x_new = np.random.uniform(-5.0, 5.0, size=self.dim)

            f = func(x_new)
            if f < self.f_opt:
                self.f_opt = f
                self.x_opt = x_new

        return self.f_opt, self.x_opt

