class EnhancedAdaptiveSAOptimizer:
    def __init__(self, budget=10000, dim=10, T_start=100, alpha=0.95, sigma_start=1):
        self.budget = budget
        self.dim = dim
        self.T = T_start
        self.alpha = alpha
        self.sigma = sigma_start

    def __call__(self, func):
        self.f_opt = np.inf
        self.x_opt = np.random.uniform(func.bounds.lb, func.bounds.ub)
        for i in range(self.budget):
            x_new = self.x_opt + np.random.normal(0, self.sigma, self.dim)
            f_new = func(x_new)
            if (f_new < self.f_opt) or (np.exp((self.f_opt - f_new) / self.T) > np.random.rand()):
                self.f_opt, self.x_opt = f_new, x_new
            if i % 10 == 0: # Probabilistically adjust step size every 10 iterations
                if self.f_opt < func(self.x_opt + np.random.normal(0, self.sigma * 1.05, self.dim)):
                    self.sigma *= 0.95
                else:
                    self.sigma *= 1.05
            self.T *= self.alpha # Decay temperature after each iteration
        return self.f_opt, self.x_opt

