class CoordinateDescentOptimizer:
    def __init__(self, budget=10000, dim=10, alpha=0.05):
        self.budget = budget
        self.dim = dim
        self.alpha = alpha  # learning rate

    def __call__(self, func):
        x = np.random.uniform(func.bounds.lb, func.bounds.ub, size=self.dim)
        f_opt = func(x)
        x_opt = x.copy()

        for _ in range(self.budget):
            for i in range(self.dim):
                x[i] += self.alpha if np.random.rand() < 0.5 else -self.alpha
                f = func(x)
                if f < f_opt:
                    f_opt = f
                    x_opt[i] = x[i]
                else:
                    x[i] -= 2*self.alpha if np.random.rand() < 0.5 else -2*self.alpha
        return f_opt, x_opt

