class RefinedAdaptiveDifferentialEvolution:
    def __init__(self, budget=10000, dim=10):
        self.budget = budget
        self.dim = dim
        self.population_size = 20 * dim
        self.F = 0.8
        self.CR = 0.9

    def initialize_population(self, func):
        lb, ub = -5.0, 5.0
        population = np.random.uniform(lb, ub, (self.population_size, self.dim))
        fitness = np.array([func(ind) for ind in population])
        return population, fitness

    def mutate(self, individual, base, population):
        r0, r1, r2 = np.random.choice(np.arange(self.population_size), 3, replace=False)
        while r0 == base or r1 == base or r2 == base:
            r0, r1, r2 = np.random.choice(np.arange(self.population_size), 3, replace=False)

        mutant = population[r0] + self.F * (population[r1] - population[r2])
        return np.clip(mutant, -5.0, 5.0)

    def crossover(self, target, mutant):
        trial = np.copy(target)
        jrand = np.random.randint(0, self.dim)
        for j in range(self.dim):
            if np.random.rand() < self.CR or j == jrand:
                trial[j] = mutant[j]
        return trial

    def __call__(self, func):
        population, fitness = self.initialize_population(func)
        best_idx = np.argmin(fitness)
        f_opt = fitness[best_idx]
        x_opt = population[best_idx]

        for _ in range(self.budget - self.population_size):
            for i in range(self.population_size):
                mutant = self.mutate(population[i], i, population)
                trial = self.crossover(population[i], mutant)

                f_trial = func(trial)
                if f_trial < fitness[i]:
                    population[i] = trial
                    fitness[i] = f_trial

            new_best_idx = np.argmin(fitness)
            if fitness[new_best_idx] < f_opt:
                f_opt = fitness[new_best_idx]
                x_opt = population[new_best_idx]

        return f_opt, x_opt

