        r0, r1, r2 = np.random.choice(np.arange(self.population_size), 3, replace=False)
        while r0 == base or r1 == base or r2 == base:
            r0, r1, r2 = np.random.choice(np.arange(self.population_size), 3, replace=False)

        mutant = population[r0] + self.F * (population[r1] - population[r2])
        return np.clip(mutant, -5.0, 5.0)

