class EnhancedSimplifiedDifferentialEvolution:
    def __init__(self, budget=10000, dim=10):
        self.budget = budget
        self.dim = dim
        self.population_size = 5 * dim  # Further reduced population size
        self.F = 0.8  # Initial mutation factor
        self.CR = 0.9  # Crossover rate

    def initialize_population(self, func):
        return np.random.uniform(-5.0, 5.0, (self.population_size, self.dim))

    def mutate(self, population, base_idx, F):
        r0, r1, r2 = np.random.choice(np.arange(self.population_size), 3, replace=False)
        while r0 == base_idx or r1 == base_idx or r2 == base_idx:
            r0, r1, r2 = np.random.choice(np.arange(self.population_size), 3, replace=False)

        mutant = population[r0] + F * (population[r1] - population[r2])
        return np.clip(mutant, -5.0, 5.0)

    def crossover(self, target, mutant):
        trial = np.copy(target)
        jrand = np.random.randint(0, self.dim)
        for j in range(self.dim):
            if np.random.rand() < self.CR or j == jrand:
                trial[j] = mutant[j]
        return trial

    def __call__(self, func):
        population = self.initialize_population(func)
        fitness = [func(ind) for ind in population]
        f_opt = min(fitness)
        x_opt = population[fitness.index(f_opt)]

        for _ in range(self.budget - self.population_size):
            new_population = []
            new_fitness = []

            for i, ind in enumerate(population):
                F = 0.8 + 0.2 * np.random.rand()  # Adaptive mutation factor
                mutant = self.mutate(population, i, F)
                trial = self.crossover(ind, mutant)

                f_trial = func(trial)
                if f_trial < fitness[i]:
                    new_population.append(trial)
                    new_fitness.append(f_trial)
                else:
                    new_population.append(ind)
                    new_fitness.append(fitness[i])

            population = new_population
            fitness = new_fitness

            new_f_opt = min(fitness)
            if new_f_opt < f_opt:
                f_opt = new_f_opt
                x_opt = population[fitness.index(new_f_opt)]

        return f_opt, x_opt

