                    new_population.append(population[i])
                    new_fitness.append(fitness[i])

            population = np.array(new_population)
            fitness = np.array(new_fitness)

            new_best_idx = np.argmin(fitness)
            if fitness[new_best_idx] < f_opt:
                f_opt = fitness[new_best_idx]
                x_opt = population[new_best_idx]

        return f_opt, x_opt

import numpy as np

class RefinedSimplifiedAdaptiveDifferentialEvolution:
    def __init__(self, budget=10000, dim=10):
        self.budget = budget
        self.dim = dim
        self.population_size = 4 * dim  # Further reduced population size
        self.F = 0.85  # Increased mutation scaling factor
        self.CR = 0.9  # Reduced crossover probability

    def initialize_population(self, func):
        population = np.random.uniform(-5.0, 5.0, (self.population_size, self.dim))
        fitness = np.array([func(ind) for ind in population])
        return population, fitness

    def mutate(self, individual, base, population):
        r0, r1, r2 = np.random.choice(np.arange(self.population_size), 3, replace=False)
        while r0 == base or r1 == base or r2 == base:
            r0, r1, r2 = np.random.choice(np.arange(self.population_size), 3, replace=False)

        mutant = population[r0] + self.F * (population[r1] - population[r2])
        return np.clip(mutant, -5.0, 5.0)

    def crossover(self, target, mutant):
        trial = np.copy(target)
        jrand = np.random.randint(0, self.dim)
        for j in range(self.dim):
            if np.random.rand() < self.CR or j == jrand:
                trial[j] = mutant[j]
        return trial

    def __call__(self, func):
        population, fitness = self.initialize_population(func)
        best_idx = np.argmin(fitness)
        f_opt = fitness[best_idx]
        x_opt = population[best_idx]

        for _ in range(self.budget - self.population_size):
            new_population = []
            new_fitness = []

            for i in range(self.population_size):
                mutant = self.mutate(population[i], i, population)
                trial = self.crossover(population[i], mutant)

                f_trial = func(trial)
                if f_trial < fitness[i]:
                    new_population.append(trial)
                    new_fitness.append(f_trial)
                else:
                    new_population.append(population[i])
                    new_fitness.append(fitness[i])

            population = np.array(new_population)
            fitness = np.array(new_fitness)

            new_best_idx = np.argmin(fitness)
            if fitness[new_best_idx] < f_opt:
                f_opt = fitness[new_best_idx]
                x_opt = population[new_best_idx]

        return f_opt, x_opt

import numpy as np

class NovelHeuristicOptimizer:
    def __init__(self, budget=10000, dim=10, step_size=0.1):
        self.budget = budget
        self.dim = dim
        self.step_size = step_size
        self.bounds = (-5.0, 5.0)

    def mutate(self, x):
        mutation_rate = np.random.rand()
        if mutation_rate < 0.3:
            return np.clip(x + np.random.normal(0, self.step_size, self.dim), *self.bounds)
        elif mutation_rate < 0.6:
            return np.clip(x + np.random.uniform(-self.step_size, self.step_size, self.dim), *self.bounds)
        else:
            return x

    def local_search(self, func, x):
        f_best = func(x)
        for _ in range(10):  # Local search depth
            candidate = self.mutate(x)
            f_candidate = func(candidate)
            if f_candidate < f_best:
                f_best = f_candidate
                x = candidate
        return f_best, x

    def __call__(self, func):
        self.f_opt = np.Inf
        self.x_opt = None
        x_current = np.random.uniform(self.bounds[0], self.bounds[1], self.dim)

        for _ in range(self.budget):
            f_current, x_current = self.local_search(func, x_current)

            if f_current < self.f_opt:
                self.f_opt = f_current
                self.x_opt = x_current

            # Adaptive step size adjustment
            if np.random.rand() < 0.1 and self.step_size > 0.01:
                self.step_size *= 0.9

        return self.f_opt, self.x_opt

