    def local_search(self, func, x, step_size):
        f_best = func(x)
        for _ in range(10):  # Increased local search depth
            candidate = self.mutate(x, step_size)
            f_candidate = func(candidate)
            if f_candidate < f_best:
                f_best = f_candidate
                x = candidate
        return f_best, x

    def __call__(self, func):
        self.f_opt = np.Inf
        self.x_opt = None
        x_current = np.random.uniform(self.bounds[0], self.bounds[1], self.dim)
        step_size = 0.5

        for _ in range(self.budget):
            f_current, x_current = self.local_search(func, x_current, step_size)

            if f_current < self.f_opt:
                self.f_opt = f_current
                self.x_opt = x_current

            # Adaptive step size adjustment based on improvement
            if np.random.rand() < 0.1 and f_current < func(x_current - step_size * np.random.normal(0, 1, self.dim)):
                step_size *= 0.95
            elif np.random.rand() < 0.05:
                step_size = min(step_size * 1.1, 2.0)

        return self.f_opt, self.x_opt

