import numpy as np

class DifferentialEvolutionOptimizer:
    def __init__(self, budget=10000, dim=10, F=0.8, CR=0.7):
        self.budget = budget
        self.dim = dim
        self.F = F  # Scaling factor for mutation
        self.CR = CR  # Crossover rate
        self.pop_size = min(100, budget)
        self.lb = -5.0
        self.ub = 5.0

    def __call__(self, func):
        pop = np.random.uniform(low=self.lb, high=self.ub, size=(self.pop_size, self.dim))
        fitness = np.array([func(ind) for ind in pop])

        for _ in range(self.budget):
            mutants = self.mutate(pop)
            trial_vectors = self.crossover(pop, mutants)
            trial_fitness = np.array([func(tv) for tv in trial_vectors])

            for i in range(self.pop_size):
                if trial_fitness[i] < fitness[i]:
                    pop[i], fitness[i] = trial_vectors[i], trial_fitness[i]

        return np.min(fitness), pop[np.argmin(fitness)]

    def mutate(self, pop):
        r1, r2, r3 = np.random.choice(np.arange(self.pop_size), size=(3, self.pop_size))
        return pop[r1] + self.F * (pop[r2] - pop[r3])

    def crossover(self, pop, mutants):
        j = np.random.randint(0, self.dim)
        mask = np.random.rand(self.pop_size, self.dim) < self.CR
        mask[:, j] = True  # Ensure at least one dimension is updated
        return np.where(mask, mutants, pop)

import numpy as np

class AdaptiveDifferentialEvolution:
    def __init__(self, budget=10000, dim=10, pop_size=50, F=0.8, CR=0.9):
        self.budget = budget
        self.dim = dim
        self.pop_size = pop_size
        self.F = F  # Scaling factor for mutation
        self.CR = CR  # Crossover rate

    def __call__(self, func):
        population = np.random.uniform(func.bounds.lb, func.bounds.ub, (self.pop_size, self.dim))
        fitness = [func(ind) for ind in population]
        best_idx = np.argmin(fitness)

        for _ in range(self.budget):
            for i in range(self.pop_size):
                if i == best_idx:
                    continue

                idxs = [idx for idx in range(self.pop_size) if idx != i and idx != best_idx]
                a, b, c = population[np.random.choice(idxs, 3, replace=False)]
                mutant = np.clip(a + self.F * (b - c), func.bounds.lb, func.bounds.ub)
                trial = np.where(np.random.rand(self.dim) < self.CR, mutant, population[i])
                f_trial = func(trial)

                if f_trial < fitness[i]:
                    population[i], fitness[i] = trial, f_trial
                    if f_trial < fitness[best_idx]:
                        best_idx = i

            if _ % (self.pop_size * 10) == 0:
                self.F *= 0.95
                self.CR *= 0.99

        return min(fitness), population[best_idx]

import numpy as np

class RandomHillClimbSearch:
    def __init__(self, budget=10000, dim=10, step_size=0.1):
        self.budget = budget
        self.dim = dim
        self.step_size = step_size

    def hill_climb(self, x, func, budget):
        for _ in range(budget):
            x_new = np.clip(x + np.random.uniform(-self.step_size, self.step_size, size=self.dim), -5.0, 5.0)
            f_new = func(x_new)
            if f_new < func(x):
                x = x_new
        return x

    def __call__(self, func):
        self.f_opt = np.Inf
        self.x_opt = None
        for i in range(self.budget):
            x = np.random.uniform(-5.0, 5.0, size=self.dim)
            x = self.hill_climb(x, func, self.budget // self.dim)
            f = func(x)
            if f < self.f_opt:
                self.f_opt = f
                self.x_opt = x
        return self.f_opt, self.x_opt

import numpy as np

class RandomHillClimbSearchOptimizer:
    def __init__(self, budget=10000, dim=10, step_size=0.1):
        self.budget = budget
        self.dim = dim
        self.step_size = step_size

    def local_search(self, x, func, local_budget):
        for _ in range(local_budget):
            neighbors = np.random.uniform(-self.step_size, self.step_size, size=(10, self.dim)) + x
            neighbors = np.clip(neighbors, -5.0, 5.0)
            f_new = func(neighbors)
            best_idx = np.argmin(f_new)
            if f_new[best_idx] < func(x):
                x = neighbors[best_idx]
        return x

    def __call__(self, func):
        self.f_opt = np.Inf
        self.x_opt = None
        for i in range(self.budget // self.dim):
            x = np.random.uniform(-5.0, 5.0, size=self.dim)
            x = self.local_search(x, func, self.dim)
            f = func(x)
            if f < self.f_opt:
                self.f_opt = f
                self.x_opt = x
        return self.f_opt, self.x_opt

import numpy as np

class RandomSimulatedAnnealingSearch:
    def __init__(self, budget=10000, dim=10, start_temp=100, end_temp=1):
        self.budget = budget
        self.dim = dim
        self.start_temp = start_temp
        self.end_temp = end_temp

    def simulated_annealing(self, x, func, temp):
        for _ in range(self.budget // self.dim):
            x_new = np.clip(x + np.random.normal(size=self.dim), -5.0, 5.0)
            delta_f = func(x_new) - func(x)
            if delta_f < 0 or np.exp(-delta_f / temp) > np.random.rand():
                x = x_new
        return x

    def __call__(self, func):
        self.f_opt = np.Inf
        self.x_opt = None
        for i in range(self.budget // self.dim):
            temp = self.start_temp * (self.end_temp / self.start_temp) ** (i / self.budget)
            x = np.random.uniform(-5.0, 5.0, size=self.dim)
            x = self.simulated_annealing(x, func, temp)
            f = func(x)
            if f < self.f_opt:
