class ImprovedRandomHillClimbSearchOptimizer:
    def __init__(self, budget=10000, dim=10, step_size=0.1):
        self.budget = budget
        self.dim = dim
        self.step_size = step_size

    def local_search(self, x, func, local_budget):
        for _ in range(local_budget):
            directions = np.random.choice([-1, 0, 1], size=self.dim)
            neighbor = x + self.step_size * directions
            neighbor = np.clip(neighbor, -5.0, 5.0)
            f_new = func(neighbor)
            if f_new < func(x):
                x = neighbor
        return x

    def __call__(self, func):
        self.f_opt = np.Inf
        self.x_opt = None
        for i in range(self.budget // self.dim):
            x = np.random.uniform(-5.0, 5.0, size=self.dim)
            x = self.local_search(x, func, self.dim)
            f = func(x)
            if f < self.f_opt:
                self.f_opt = f
                self.x_opt = x
        return self.f_opt, self.x_opt

import numpy as np

class SimplifiedSimulatedAnnealingSearch:
    def __init__(self, budget=10000, dim=10, start_temp=100):
        self.budget = budget
        self.dim = dim
        self.start_temp = start_temp

    def anneal(self, x, func, temp):
        for _ in range(self.budget // self.dim):
            x_new = np.clip(x + np.random.normal(size=self.dim), -5.0, 5.0)
            delta_f = func(x_new) - func(x)
            if delta_f < 0 or np.exp(-delta_f / temp) > np.random.rand():
                x = x_new
        return x

    def __call__(self, func):
        self.f_opt = np.Inf
        self.x_opt = None
        for i in range(self.budget // self.dim):
            temp = self.start_temp / (i + 1)
            x = np.random.uniform(-5.0, 5.0, size=self.dim)
            x = self.anneal(x, func, temp)
            f = func(x)
            if f < self.f_opt:
                self.f_opt = f
                self.x_opt = x
        return self.f_opt, self.x_opt

