class RefinedSimulatedAnnealingSearch:
    def __init__(self, budget=10000, dim=10, start_temp=500, end_temp=1):
        self.budget = budget
        self.dim = dim
        self.start_temp = start_temp
        self.end_temp = end_temp

    def simulated_annealing(self, x, func, temp):
        for _ in range(int(self.budget / self.dim)):
            x_new = np.clip(x + np.random.normal(size=self.dim) * 0.1, -5.0, 5.0) # Adjusting the step size to control exploration and exploitation
            delta_f = func(x_new) - func(x)
            if delta_f < 0 or np.exp(-delta_f / temp) > np.random.rand():
                x = x_new
        return x

    def __call__(self, func):
        self.f_opt = np.Inf
        self.x_opt = None
        x = np.random.uniform(-5.0, 5.0, size=self.dim) # Initializing with a random solution
        for i in range(int(self.budget / self.dim)):
            temp = self.start_temp * (self.end_temp / self.start_temp) ** (i / (self.budget / self.dim)) # Linearly decreasing the temperature
            x = self.simulated_annealing(x, func, temp) # Applying simulated annealing to update the solution
            f = func(x)
            if f < self.f_opt:
                self.f_opt = f
                self.x_opt = x
        return self.f_opt, self.x_opt

