class EnhancedAdaptiveGaussianSampling:
    def __init__(self, budget=10000, dim=10, initial_std=2.0):
        self.budget = budget
        self.dim = dim
        self.initial_std = initial_std
        self.bounds = np.array([-5.0, 5.0])

    def __call__(self, func):
        x_best = np.random.uniform(self.bounds[0], self.bounds[1], self.dim)
        f_best = func(x_best)

        std = self.initial_std

        for _ in range(1, self.budget):
            x_candidate = np.clip(np.random.normal(x_best, std), self.bounds[0], self.bounds[1])

            f_candidate = func(x_candidate)

            if f_candidate < f_best:
                x_best, f_best = x_candidate, f_candidate
                std *= 1.05  # Increase step size on improvement
            else:
                std *= 0.98  # Decrease step size otherwise

        return f_best, x_best

