class HybridOptimization:
    def __init__(self, budget=10000, dim=10, alpha=0.5):
        self.budget = budget
        self.dim = dim
        self.alpha = alpha  # Probability of global exploration

    def __call__(self, func):
        lb, ub = -5.0, 5.0
        self.f_opt = np.Inf
        self.x_opt = None

        # Initialize population with random points
        population = np.random.uniform(lb, ub, (self.budget, self.dim))

        for i in range(self.budget):
            if np.random.rand() < self.alpha:
                # Global exploration: sample a new point randomly
                x_new = np.random.uniform(lb, ub, self.dim)
            else:
                # Local exploitation: perform a local search around the best point found so far
                if self.x_opt is not None:
                    perturbation = np.clip(np.random.normal(0, 1, self.dim), -0.5, 0.5)
                    x_new = np.clip(self.x_opt + perturbation, lb, ub)
                else:
                    # If no best point found yet, explore randomly
                    x_new = np.random.uniform(lb, ub, self.dim)

            f_new = func(x_new)
            if f_new < self.f_opt:
                self.f_opt = f_new
                self.x_opt = x_new

        return self.f_opt, self.x_opt

