import numpy as np

class AdaptiveDifferentialEvolution:
    def __init__(self, budget=10000, dim=10, pop_size=20, archive_size=10):
        self.budget = budget
        self.dim = dim
        self.pop_size = pop_size
        self.archive_size = archive_size
        self.F = 0.5  # Mutation factor
        self.Cr = 0.9 # Crossover rate
        self.pop = None
        self.fitness = None
        self.archive = []
        self.archive_fitness = []

    def initialize_population(self, func):
        self.pop = np.random.uniform(func.bounds.lb, func.bounds.ub, size=(self.pop_size, self.dim))
        self.fitness = np.array([func(x) for x in self.pop])
        self.budget -= self.pop_size

    def mutate(self, i):
        idxs = [idx for idx in range(self.pop_size) if idx != i]
        if self.archive:
            idxs.append(np.random.randint(len(self.archive)) + self.pop_size)
            a, b, c = np.random.choice(idxs, 3, replace=False)
            if a >= self.pop_size:
                a_vec = self.archive[a - self.pop_size]
            else:
                a_vec = self.pop[a]

            if b >= self.pop_size:
                b_vec = self.archive[b - self.pop_size]
            else:
                b_vec = self.pop[b]
            if c >= self.pop_size:
                c_vec = self.archive[c - self.pop_size]
            else:
                c_vec = self.pop[c]

            mutant = a_vec + self.F * (b_vec - c_vec)
        else:
            a, b, c = np.random.choice(idxs, 3, replace=False)
            mutant = self.pop[a] + self.F * (self.pop[b] - self.pop[c])

        mutant = np.clip(mutant, -5.0, 5.0)
        return mutant

    def crossover(self, mutant, i):
        trial = np.copy(self.pop[i])
        j_rand = np.random.randint(self.dim)
        for j in range(self.dim):
            if np.random.rand() < self.Cr or j == j_rand:
                trial[j] = mutant[j]
        return trial

    def selection(self, func, trial, i):
        f_trial = func(trial)
        self.budget -= 1
        if f_trial < self.fitness[i]:
            if len(self.archive) < self.archive_size:
                self.archive.append(self.pop[i])
                self.archive_fitness.append(self.fitness[i])
            else:
                idx_to_replace = np.argmax(self.archive_fitness)
                self.archive[idx_to_replace] = self.pop[i]
                self.archive_fitness[idx_to_replace] = self.fitness[i]


            self.fitness[i] = f_trial
            self.pop[i] = trial
        else:
            if len(self.archive) < self.archive_size:
                self.archive.append(self.pop[i])
                self.archive_fitness.append(self.fitness[i])
            else:
                idx_to_replace = np.argmax(self.archive_fitness)
                if self.fitness[i] < self.archive_fitness[idx_to_replace]:
                    self.archive[idx_to_replace] = self.pop[i]
                    self.archive_fitness[idx_to_replace] = self.fitness[i]


    def __call__(self, func):
        self.f_opt = np.Inf
        self.x_opt = None
        self.initialize_population(func)

        while self.budget > 0:
            for i in range(self.pop_size):
                if self.budget <= 0:
                    break
                mutant = self.mutate(i)
                trial = self.crossover(mutant, i)
                self.selection(func, trial, i)

            best_index = np.argmin(self.fitness)
            if self.fitness[best_index] < self.f_opt:
                self.f_opt = self.fitness[best_index]
                self.x_opt = self.pop[best_index]

        return self.f_opt, self.x_opt

import numpy as np

class AdaptiveDifferentialEvolution:
    def __init__(self, budget=10000, dim=10, F=0.5, CR=0.7):
        self.budget = budget
        self.dim = dim
        self.F = F  # Differential weight factor
        self.CR = CR  # Crossover probability
        self.bounds = (-5.0, 5.0)

    def __call__(self, func):
        population_size = int(np.ceil(10 * np.log(self.dim)))
        population = np.random.uniform(low=self.bounds[0], high=self.bounds[1], size=(population_size, self.dim))
        fitness_values = [func(ind) for ind in population]

        best_index = np.argmin(fitness_values)
        f_opt = fitness_values[best_index]
        x_opt = population[best_index]

        budget_spent = population_size

        while budget_spent < self.budget:
            new_population = np.copy(population)
            for i in range(population_size):
                if np.random.rand() < self.CR or i == best_index:
                    a, b, c = np.random.choice([j for j in range(population_size) if j != i], 3, replace=False)
                    mutant = population[a] + self.F * (population[b] - population[c])

                    # Local search
                    candidate = self.local_search(func, mutant, budget_spent, self.budget)
                    f_candidate = func(candidate)

                    if f_candidate < fitness_values[i]:
                        new_population[i] = candidate
                        fitness_values[i] = f_candidate

                        if f_candidate < f_opt:
                            f_opt = f_candidate
                            x_opt = candidate

            population = new_population
            budget_spent += population_size

        return f_opt, x_opt

    def local_search(self, func, x, start_budget, end_budget):
        step = 0.1
        while start_budget < end_budget:
            improved = False
            for i in range(self.dim):
                if np.random.rand() > 0.5:
                    new_x = x.copy()
                    new_x[i] += step
                    if self.bounds[0] <= new_x[i] <= self.bounds[1]:
                        f_new = func(new_x)
                        start_budget += 1
                        if f_new < func(x):
                            x = new_x
                            improved = True

                if np.random.rand() > 0.5:
                    new_x = x.copy()
                    new_x[i] -= step
                    if self.bounds[0] <= new_x[i] <= self.bounds[1]:
                        f_new = func(new_x)
                        start_budget += 1
                        if f_new < func(x):
                            x = new_x
                            improved = True

            if not improved:
                break

        return x

import numpy as np

class GeneticLocalSearch:
    def __init__(self, budget=10000, dim=10, population_size=50, mutation_rate=0.1):
        self.budget = budget
        self.dim = dim
        self.population_size = population_size
        self.mutation_rate = mutation_rate

    def initialize_population(self, lb, ub):
        return np.random.uniform(lb, ub, (self.population_size, self.dim))

    def mutate(self, individual, lb, ub):
        for i in range(len(individual)):
            if np.random.rand() < self.mutation_rate:
                individual[i] = np.random.uniform(lb[i], ub[i])
        return individual

    def crossover(self, parent1, parent2):
        child = np.zeros_like(parent1)
        for i in range(self.dim):
            if np.random.rand() < 0.5:
                child[i] = parent1[i]
            else:
                child[i] = parent2[i]
        return child

    def local_search(self, x, func, lb, ub, max_iter=10):
        best_x = x
        best_f = func(x)
        for _ in range(max_iter):
            candidate = self.mutate(best_x.copy(), lb, ub)
            candidate_f = func(candidate)
            if candidate_f < best_f:
                best_x = candidate
                best_f = candidate_f
        return best_x

    def __call__(self, func):
        lb = np.full(self.dim, -5.0)
        ub = np.full(self.dim, 5.0)

        population = self.initialize_population(lb, ub)
        evaluations = self.population_size

        while evaluations < self.budget:
            fitnesses = [func(ind) for ind in population]

            sorted_indices = np.argsort(fitnesses)
            best_individual = population[sorted_indices[0]]
            best_fitness = fitnesses[sorted_indices[0]]

            new_population = []
            for i in range(self.population_size):
                parent1 = population[sorted_indices[i % self.population_size]]
                parent2 = population[sorted_indices[(i + 1) % self.population_size]]
                child = self.crossover(parent1, parent2)
                child = self.mutate(child, lb, ub)
                new_population.append(child)

            population = np.array(new_population)
            evaluations += self.population_size

            best_individual = self.local_search(best_individual, func, lb, ub)
            if func(best_individual) < best_fitness:
                best_fitness = func(best_individual)

        return best_fitness, best_individual

