import numpy as np

class OptimizedSimulatedAnnealingOptimizer:
    def __init__(self, budget=10000, dim=10, T_init=1.0, alpha=0.99):
        self.budget = budget
        self.dim = dim
        self.T_init = T_init
        self.alpha = alpha

    def __call__(self, func):
        x_current = np.random.uniform(func.bounds.lb, func.bounds.ub)
        f_current = func(x_current)
        self.f_opt = f_current
        self.x_opt = x_current
        T = self.T_init

        for _ in range(self.budget):
            x_new = np.clip(x_current + np.random.normal(0, 1), func.bounds.lb, func.bounds.ub)
            f_new = func(x_new)

            if self._acceptance_probability(f_new, f_current, T) > np.random.rand():
                x_current = x_new
                f_current = f_new

            if f_new < self.f_opt:
                self.f_opt = f_new
                self.x_opt = x_new

            T *= self.alpha
        return self.f_opt, self.x_opt

    def _acceptance_probability(self, new_val, current_val, temp):
        if new_val < current_val:
            return 1.0
        else:
            return np.exp((current_val - new_val) / temp)

import numpy as np

class AdaptiveLocalSearch:
    def __init__(self, budget=10000, dim=10, mutation_rate=0.1):
        self.budget = budget
        self.dim = dim
        self.mutation_rate = mutation_rate
        self.bounds = (-5.0, 5.0)

    def mutate(self, x):
        return np.clip(x + np.random.normal(0, self.mutation_rate, self.dim), *self.bounds)

    def local_search(self, func, x):
        best_x = x
        for _ in range(max(1, int(self.budget * 0.1))):
            candidate = self.mutate(best_x)
            if func(candidate) < func(best_x):
                best_x = candidate
        return best_x

    def __call__(self, func):
        self.f_opt = np.inf
        self.x_opt = None

        x0 = np.random.uniform(*self.bounds, self.dim)
        for i in range(self.budget):
            if i % 100 == 0:
                x0 = self.local_search(func, x0)

            f = func(x0)
            if f < self.f_opt:
                self.f_opt = f
                self.x_opt = x0

            x0 = self.mutate(x0)

        return self.f_opt, self.x_opt

