class NovelHeuristicOptimizer:
    def __init__(self, budget=10000, dim=10):
        self.budget = budget
        self.dim = dim
        self.bounds = (-5.0, 5.0)

    def _initialize_population(self):
        return np.random.uniform(self.bounds[0], self.bounds[1], (self.dim, self.budget))

    def _mutation(self, x, mutation_rate=0.1):
        noise = np.random.normal(0, mutation_rate, self.dim)
        return np.clip(x + noise, *self.bounds)

    def __call__(self, func):
        population = self._initialize_population()
        fitness = np.array([func(ind) for ind in population.T])

        best_idx = np.argmin(fitness)
        best_solution = population[:, best_idx]

        for _ in range(self.budget - 1):  # Main loop with adaptive refinement
            new_solution = self._mutation(best_solution)
            new_fitness = func(new_solution)

            if new_fitness < fitness[best_idx]:
                best_solution = new_solution
                fitness[best_idx] = new_fitness

        return fitness[best_idx], best_solution.T

