import numpy as np

class EnhancedDE:
    def __init__(self, budget=10000, dim=10):
        self.budget = budget
        self.dim = dim
        self.mutation_rate = 0.8
        self.crossover_rate = 0.7

    def __call__(self, func):
        lb, ub = -5.0, 5.0
        population_size = int(np.sqrt(self.budget))
        population = np.random.uniform(lb, ub, (population_size, self.dim))
        fitness = np.array([func(ind) for ind in population])

        for _ in range(self.budget):
            for i in range(population_size):
                indices = list(range(population_size))
                indices.remove(i)
                a, b, c = np.random.choice(indices, 3, replace=False)

                candidate = np.zeros_like(population[i])
                for j in range(self.dim):
                    if np.random.rand() < self.crossover_rate or i == 0:
                        candidate[j] = population[a][j] + self.mutation_rate * (population[b][j] - population[c][j])
                    else:
                        candidate[j] = population[i][j]

                candidate = np.clip(candidate, lb, ub)

                f_candidate = func(candidate)
                if f_candidate < fitness[i]:
                    population[i] = candidate
                    fitness[i] = f_candidate

        best_idx = np.argmin(fitness)
        return fitness[best_idx], population[best_idx]

import numpy as np

class AdaptiveHillClimbing:
    def __init__(self, budget=10000, dim=10, step_size=0.1):
        self.budget = budget
        self.dim = dim
        self.step_size = step_size
        self.bounds = (-5.0, 5.0)

    def _random_sample(self):
        return np.random.uniform(self.bounds[0], self.bounds[1], self.dim)

    def _local_search(self, x):
        best_x = x.copy()
        best_f = float('inf')
        for i in range(self.dim):
            for dx in [-self.step_size, self.step_size]:
                candidate_x = best_x + np.zeros_like(best_x)
                candidate_x[i] += dx
                candidate_f = self.func(candidate_x)
                if candidate_f < best_f:
                    best_f = candidate_f
                    best_x = candidate_x
        return best_x, best_f

    def __call__(self, func):
        self.func = func
        self.f_opt = np.Inf
        self.x_opt = None

        for _ in range(self.budget):
            x = self._random_sample()
            f = func(x)
            if f < self.f_opt:
                self.f_opt = f
                self.x_opt = x

            # Perform local search from the current best point
            local_x, local_f = self._local_search(self.x_opt)
            if local_f < self.f_opt:
                self.f_opt = local_f
                self.x_opt = local_x

        return self.f_opt, self.x_opt

