class RefinedAdaptiveHillClimbing:
    def __init__(self, budget=10000, dim=10):
        self.budget = budget
        self.dim = dim
        self.bounds = (-5.0, 5.0)
        self.step_size = np.full(dim, 0.5)  # Initial step size for each dimension

    def _random_sample(self):
        return np.random.uniform(self.bounds[0], self.bounds[1], self.dim)

    def _local_search(self, x):
        best_x = x.copy()
        best_f = self.func(x)

        for i in range(self.dim):
            for dx in [-self.step_size[i], self.step_size[i]]:
                candidate_x = best_x + np.zeros_like(best_x)
                candidate_x[i] += dx
                candidate_f = self.func(candidate_x)

                if candidate_f < best_f:
                    best_f = candidate_f
                    best_x = candidate_x

        # Adjust step size based on success
        if best_f < self.f_opt:
            self.step_size *= 0.95  # Reduce step size if improvement found
        else:
            self.step_size *= 1.05  # Increase step size if no improvement

        return best_x, best_f

    def __call__(self, func):
        self.func = func
        self.f_opt = np.Inf
        self.x_opt = None

        for _ in range(self.budget):
            x = self._random_sample()
            f = func(x)
            if f < self.f_opt:
                self.f_opt = f
                self.x_opt = x

            # Perform local search from the current best point
            self.x_opt, self.f_opt = self._local_search(self.x_opt)

        return self.f_opt, self.x_opt

