import numpy as np

class HybridSearch:
    def __init__(self, budget=10000, dim=10, random_search_ratio=0.75):
        self.budget = budget
        self.dim = dim
        self.random_search_budget = int(budget * random_search_ratio)
        self.gradient_descent_budget = budget - self.random_search_budget
        self.learning_rate = 0.1

    def gradient_descent(self, func, x):
        for _ in range(self.gradient_descent_budget):
            grad = (func(x + np.full(self.dim, self.learning_rate)) - func(x)) / self.learning_rate
            x -= self.learning_rate * grad
        return func(x), x

    def __call__(self, func):
        self.f_opt = np.Inf
        self.x_opt = None
        for _ in range(self.random_search_budget):
            x = np.random.uniform(-5.0, 5.0, self.dim)
            f = func(x)
            if f < self.f_opt:
                self.f_opt = f
                self.x_opt = x
        return self.gradient_descent(func, self.x_opt)

import numpy as np

class HybridOptimizer:
    def __init__(self, budget=10000, dim=10, learning_rate=0.1):
        self.budget = budget
        self.dim = dim
        self.learning_rate = learning_rate

    def gradient(self, func, x, h):
        grad = np.zeros(self.dim)
        for i in range(self.dim):
            d = np.zeros(self.dim)
            d[i] = h
            grad[i] = (func(x + d) - func(x)) / h
        return grad

    def __call__(self, func):
        x_best = np.random.uniform(-5.0, 5.0, self.dim)
        f_best = func(x_best)

        for _ in range(self.budget // 2):
            x_new = np.random.uniform(-5.0, 5.0, self.dim)
            f_new = func(x_new)
            if f_new < f_best:
                x_best, f_best = x_new, f_new

        for _ in range(self.budget // 2):
            grad = self.gradient(func, x_best, 1e-6)
            x_best -= self.learning_rate * grad

        return func(x_best), x_best

import numpy as np

class HybridSearchRefined:
    def __init__(self, budget=10000, dim=10, exploration_rate=0.75):
        self.budget = budget
        self.dim = dim
        self.exploration_budget = int(budget * exploration_rate)
        self.exploitation_budget = budget - self.exploration_budget
        self.learning_rate = 0.1

    def gradient_descent(self, func, x):
        for _ in range(self.exploitation_budget // self.dim):
            grad = np.zeros(self.dim)
            epsilon = np.full(self.dim, 1e-4)
            fx = func(x)
            for i in range(self.dim):
                x[i] += epsilon[i]
                grad[i] = (func(x) - fx) / epsilon[i]
                x[i] -= epsilon[i]
            x -= self.learning_rate * grad
        return func(x), x

    def __call__(self, func):
        self.f_opt = np.Inf
        self.x_opt = None
        for _ in range(self.exploration_budget):
            x = np.random.uniform(-5.0, 5.0, self.dim)
            f = func(x)
            if f < self.f_opt:
                self.f_opt = f
                self.x_opt = x
        return self.gradient_descent(func, self.x_opt)

import numpy as np

class GravitationalSearchAlgorithm:
    def __init__(self, budget=10000, dim=10, G=0.4, alpha=0.9):
        self.budget = budget
        self.dim = dim
        self.G = G  # Gravitational constant
        self.alpha = alpha  # Inertia weight
        self.population_size = int(np.sqrt(budget))
        self.bounds = (-5.0, 5.0)

    def initialize_population(self):
        return np.random.uniform(self.bounds[0], self.bounds[1], (self.population_size, self.dim))

    def calculate_fitness(self, population, func):
        fitness_values = []
        for i in range(len(population)):
            fitness_values.append(func(population[i]))
        return np.array(fitness_values)

    def update_position(self, current_pos, best_solution, distance, fitness_best, fitness_current):
        force = self.G * ((fitness_best - fitness_current) / (distance + 1e-10))
        new_velocity = self.alpha * np.random.rand() * (best_solution - current_pos) * force
        return current_pos + new_velocity

    def __call__(self, func):
        population = self.initialize_population()
        fitness_values = self.calculate_fitness(population, func)
        best_index = np.argmin(fitness_values)
        best_solution = population[best_index]
        best_fitness = fitness_values[best_index]

        for _ in range(self.budget // self.population_size):
            new_population = []
            for i in range(len(population)):
                total_force = np.zeros(self.dim)
                for j in range(len(population)):
                    if i != j:
                        distance = np.linalg.norm(population[i] - population[j])
                        force = self.G * (fitness_values[j] - fitness_values[i]) / (distance + 1e-10)
                        total_force += force * (population[j] - population[i])

                new_velocity = self.alpha * np.random.rand() * total_force
                new_position = population[i] + new_velocity
                new_position = np.clip(new_position, self.bounds[0], self.bounds[1])
                new_population.append(new_position)

            population = np.array(new_population)
            fitness_values = self.calculate_fitness(population, func)
            current_best_index = np.argmin(fitness_values)
            if fitness_values[current_best_index] < best_fitness:
                best_solution = population[current_best_index]
                best_fitness = fitness_values[current_best_index]

        return best_fitness, best_solution

import numpy as np

class AdaptiveMutationOptimizer:
    def __init__(self, budget=10000, dim=10, mutation_rate=0.1):
        self.budget = budget
        self.dim = dim
        self.mutation_rate = mutation_rate
        self.bounds = (-5.0, 5.0)
        self.best_solution = np.random.uniform(self.bounds[0], self.bounds[1], size=self.dim)
        self.best_value = float('inf')

    def mutate(self, solution):
        mutated_solution = np.copy(solution)
        for i in range(self.dim):
            if np.random.rand() < self.mutation_rate:
                mutated_solution[i] += np.random.normal(0, (self.bounds[1] - self.bounds[0]) * 0.1)
                mutated_solution[i] = np.clip(mutated_solution[i], *self.bounds)
        return mutated_solution

    def __call__(self, func):
        for _ in range(self.budget):
            candidate = self.mutate(self.best_solution)
            candidate_value = func(candidate)

            if candidate_value < self.best_value:
                self.best_value = candidate_value
                self.best_solution = candidate
                # Adaptive mutation rate adjustment based on improvement
                self.mutation_rate = max(0.01, self.mutation_rate * 0.95)
            else:
                # Increase mutation rate if no improvement is found
                self.mutation_rate = min(0.2, self.mutation_rate * 1.05)

        return self.best_value, self.best_solution

