        self.bounds = (-5.0, 5.0)
        self.best_solution = np.random.uniform(self.bounds[0], self.bounds[1], size=self.dim)
        self.best_value = float('inf')

    def mutate(self, solution):
        mutated_solution = np.copy(solution)
        for i in range(self.dim):
            if np.random.rand() < self.mutation_rate:
                mutated_solution[i] += np.random.normal(0, (self.bounds[1] - self.bounds[0]) * 0.1)
