class AdaptiveMutationOptimizer:
    def __init__(self, budget=10000, dim=10):
        self.budget = budget
        self.dim = dim
        self.bounds = (-5.0, 5.0)
        self.best_solution = np.random.uniform(self.bounds[0], self.bounds[1], size=self.dim)
        self.best_value = float('inf')
        self.mutation_rate = 0.1

    def mutate(self, solution):
        mutated_solution = np.copy(solution) + np.random.normal(0, (self.bounds[1] - self.bounds[0]) * self.mutation_rate, size=self.dim)
        return np.clip(mutated_solution, *self.bounds)

    def __call__(self, func):
        for _ in range(self.budget):
            candidate = self.mutate(self.best_solution)
            candidate_value = func(candidate)

            if candidate_value < self.best_value:
                self.best_value = candidate_value
                self.best_solution = candidate
                self.mutation_rate *= 0.95

        return self.best_value, self.best_solution

