import numpy as np

class AdaptiveDifferentialEvolution:
    def __init__(self, budget=10000, dim=10, F=0.8, CR=0.7):
        self.budget = budget
        self.dim = dim
        self.F = F  # Scaling factor
        self.CR = CR  # Crossover probability
        self.population_size = 4 + int(3 * np.log(dim))
        self.bounds = (-5.0, 5.0)

    def initialize_population(self):
        return np.random.uniform(self.bounds[0], self.bounds[1], (self.population_size, self.dim))

    def mutate(self, population, i):
        a, b, c = np.random.choice(np.arange(self.population_size), 3, replace=False)
        while a == i or b == i or c == i:
            a, b, c = np.random.choice(np.arange(self.population_size), 3, replace=False)
        mutant = population[a] + self.F * (population[b] - population[c])
        return np.clip(mutant, self.bounds[0], self.bounds[1])

    def crossover(self, target, mutant):
        trial = np.zeros_like(target)
        for j in range(self.dim):
            if np.random.rand() < self.CR or j == np.random.randint(self.dim):
                trial[j] = mutant[j]
            else:
                trial[j] = target[j]
        return trial

    def local_search(self, x, func):
        step_size = 0.1
        for _ in range(50):  # Limited local search iterations
            neighbor = np.clip(x + np.random.uniform(-step_size, step_size, self.dim), self.bounds[0], self.bounds[1])
            if func(neighbor) < func(x):
                x = neighbor
        return x

    def __call__(self, func):
        population = self.initialize_population()
        fitness = np.array([func(ind) for ind in population])
        best_idx = np.argmin(fitness)
        f_opt = fitness[best_idx]
        x_opt = population[best_idx]

        for _ in range(self.budget - self.population_size):
            for i in range(self.population_size):
                mutant = self.mutate(population, i)
                trial = self.crossover(population[i], mutant)
                if func(trial) < fitness[i]:
                    population[i] = trial
                    fitness[i] = func(trial)
                    if fitness[i] < f_opt:
                        f_opt = fitness[i]
                        x_opt = population[i]

            # Local search on the best individual
            x_opt = self.local_search(x_opt, func)
            if func(x_opt) < f_opt:
                f_opt = func(x_opt)

        return f_opt, x_opt

