        f_best = func(x)
        step_size = 0.1
        for _ in range(max_iter):
            for d in range(len(x)):
                neighbor = np.copy(x)
                neighbor[d] += step_size
                if lb <= neighbor[d] <= ub and func(neighbor) < f_best:
                    x = neighbor
                    f_best = func(neighbor)

                neighbor[d] -= 2 * step_size
                if lb <= neighbor[d] <= ub and func(neighbor) < f_best:
                    x = neighbor
                    f_best = func(neighbor)
        return x

    def __call__(self, func):
        lb, ub = -5.0, 5.0
        population = self.initialize_population(lb, ub)
