class RefinedDEWithLocalSearch:
    def __init__(self, budget=10000, dim=10, pop_size=None, F=0.8, CR=0.7):
        self.budget = budget
        self.dim = dim
        self.pop_size = pop_size if pop_size else 20 * dim
        self.F = F  # Differential weight
        self.CR = CR  # Crossover probability

    def __call__(self, func):
        lb, ub = -5.0, 5.0
        population = np.random.uniform(lb, ub, (self.pop_size, self.dim))
        fitness = np.array([func(ind) for ind in population])

        evaluations = self.pop_size

        while evaluations < self.budget:
            for i in range(self.pop_size):
                a, b, c = np.random.choice(np.arange(self.pop_size), 3, replace=False)
                mutant = population[a] + self.F * (population[b] - population[c])
                mutant = np.clip(mutant, lb, ub)

                trial = np.zeros_like(mutant)
                for j in range(self.dim):
                    if np.random.rand() < self.CR or j == np.random.randint(self.dim):
                        trial[j] = mutant[j]
                    else:
                        trial[j] = population[i][j]

                trial_fitness = func(trial)
                evaluations += 1
                if evaluations >= self.budget:
                    break

                if trial_fitness < fitness[i]:
                    population[i] = trial
                    fitness[i] = trial_fitness

            # Simplified local search step
            for i in range(self.pop_size):
                for j in range(self.dim):
                    for step in [-0.1, 0.1]:
                        new_x = np.clip(population[i][j] + step, lb, ub)
                        new_trial = population[i].copy()
                        new_trial[j] = new_x
                        new_fitness = func(new_trial)
                        evaluations += 1
                        if evaluations >= self.budget:
                            break
                        if new_fitness < fitness[i]:
                            population[i] = new_trial
                            fitness[i] = new_fitness

        best_idx = np.argmin(fitness)
        return fitness[best_idx], population[best_idx]

import numpy as np

class HybridDESA:
    def __init__(self, budget=10000, dim=10):
        self.budget = budget
        self.dim = dim
        self.de_population_size = int(budget * 0.7)
        self.sa_iterations = budget - self.de_population_size
        self.bounds = [-5.0, 5.0]

    def de_optimization(self, func):
        population = np.random.uniform(low=self.bounds[0], high=self.bounds[1], size=(self.de_population_size, self.dim))
        for _ in range(self.de_population_size):
            indices = np.random.choice(np.arange(self.de_population_size), 3, replace=False)
            a, b, c = population[indices]
            mutant = np.clip(a + 0.5 * (b - c), self.bounds[0], self.bounds[1])
            cross_points = np.random.rand(self.dim) < 0.5
            trial = np.where(cross_points, mutant, population[_])
            if func(trial) < func(population[_]):
                population[_] = trial
        return min(population, key=func)

    def sa_optimization(self, func, initial_solution):
        current_solution = initial_solution
        for t in range(1, self.sa_iterations + 1):
            temperature = 1 / np.log(t + 1)
            candidate_solution = np.random.normal(current_solution, scale=0.1 * temperature)
            candidate_solution = np.clip(candidate_solution, self.bounds[0], self.bounds[1])
            delta_e = func(candidate_solution) - func(current_solution)
            if delta_e < 0 or np.exp(-delta_e / temperature) > np.random.rand():
                current_solution = candidate_solution
        return current_solution

    def __call__(self, func):
        initial_solution = self.de_optimization(func)
        final_solution = self.sa_optimization(func, initial_solution)
        return func(final_solution), final_solution

import numpy as np

class HybridOptimizerRefined:
    def __init__(self, budget=10000, dim=10, global_budget=0.8):
        self.budget = budget
        self.dim = dim
        self.global_budget = int(global_budget * budget)
        self.local_budget = budget - self.global_budget
        self.step_size = 0.2  # increased step size for more exploration

    def __call__(self, func):
        f_opt, x_opt = self._search(func, self.global_budget)
        f_opt, x_opt = self._hill_climb(func, f_opt, x_opt, self.local_budget)
        return f_opt, x_opt

    def _search(self, func, budget):
        f_opt = np.Inf
        x_opt = None
        for _ in range(budget):
            x = np.random.uniform(-5.0, 5.0, size=self.dim)
            f = func(x)
            if f < f_opt:
                f_opt = f
                x_opt = x
        return f_opt, x_opt

    def _hill_climb(self, func, f_opt, x_opt, budget):
        for _ in range(budget):
            x_new = np.clip(x_opt + np.random.normal(size=self.dim)*self.step_size, -5.0, 5.0)
            f_new = func(x_new)
            if f_new < f_opt:
                f_opt = f_new
                x_opt = x_new
        return f_opt, x_opt

import numpy as np

class SimulatedAnnealing:
    def __init__(self, budget=10000, dim=10, initial_temp=100.0, cooling_rate=0.95):
        self.budget = budget
        self.dim = dim
        self.initial_temp = initial_temp
        self.cooling_rate = cooling_rate
        self.current_iter = 0

    def __call__(self, func):
        current_x = np.random.uniform(func.bounds.lb, func.bounds.ub, size=self.dim)
        current_f = func(current_x)

        best_x = current_x
        best_f = current_f

        step_size = 0.1 * (func.bounds.ub - func.bounds.lb)

        for self.current_iter in range(self.budget):
            new_x = np.random.normal(loc=current_x, scale=step_size)
            new_x = np.clip(new_x, func.bounds.lb, func.bounds.ub)  # Ensure bounds are not violated
            new_f = func(new_x)

            if self._accept_solution(current_f, new_f):
                current_x = new_x
                current_f = new_f

            if new_f < best_f:
                best_x = new_x
                best_f = new_f

            step_size *= self.cooling_rate

        return best_f, best_x

    def _accept_solution(self, current_f, new_f):
        temp = self.initial_temp * (1 - self.current_iter / self.budget)  # Linear cooling schedule
        if new_f < current_f:
            return True
        else:
            return np.exp((current_f - new_f) / temp) > np.random.rand()

