import numpy as np

class ADEA:
    def __init__(self, budget=10000, dim=10, pop_size=50, cr=0.9, f=0.5, archive_size=10):
        self.budget = budget
        self.dim = dim
        self.pop_size = pop_size
        self.cr = cr
        self.f = f
        self.archive_size = archive_size

    def __call__(self, func):
        self.f_opt = np.Inf
        self.x_opt = None
        self.archive = []

        # Initialize population
        pop = np.random.uniform(func.bounds.lb, func.bounds.ub, size=(self.pop_size, self.dim))
        fitness = np.array([func(x) for x in pop])
        self.budget -= self.pop_size

        # Update optimal solution
        best_index = np.argmin(fitness)
        if fitness[best_index] < self.f_opt:
            self.f_opt = fitness[best_index]
            self.x_opt = pop[best_index]

        # Main loop
        while self.budget > 0:
            for i in range(self.pop_size):
                # Mutation
                if len(self.archive) > 0:
                    indices = np.random.choice(self.pop_size + len(self.archive), 3, replace=False)
                    if indices[0] < self.pop_size:
                        x1 = pop[indices[0]]
                    else:
                        x1 = self.archive[indices[0] - self.pop_size]
                    if indices[1] < self.pop_size:
                        x2 = pop[indices[1]]
                    else:
                        x2 = self.archive[indices[1] - self.pop_size]
                    if indices[2] < self.pop_size:
                        x3 = pop[indices[2]]
                    else:
                        x3 = self.archive[indices[2] - self.pop_size]
                else:
                    indices = np.random.choice(self.pop_size, 3, replace=False)
                    x1 = pop[indices[0]]
                    x2 = pop[indices[1]]
                    x3 = pop[indices[2]]

                v = pop[i] + self.f * (x2 - x3)
                v = np.clip(v, func.bounds.lb, func.bounds.ub)

                # Crossover
                j_rand = np.random.randint(self.dim)
                u = np.zeros(self.dim)
                for j in range(self.dim):
                    if np.random.rand() < self.cr or j == j_rand:
                        u[j] = v[j]
                    else:
                        u[j] = pop[i, j]

                # Selection
                f_u = func(u)
                self.budget -= 1
                if f_u < fitness[i]:
                    # Add replaced vector to archive
                    if len(self.archive) < self.archive_size:
                        self.archive.append(pop[i].copy())
                    else:
                        self.archive[np.random.randint(self.archive_size)] = pop[i].copy()
                    pop[i] = u
                    fitness[i] = f_u

                    # Update optimal solution
                    if f_u < self.f_opt:
                        self.f_opt = f_u
                        self.x_opt = u
                else:
                    pass

        return self.f_opt, self.x_opt

