        self.dim = dim
        self.initial_variance = initial_variance
        self.variance = initial_variance
        self.reduction_factor = reduction_factor
        self.exploration_ratio = exploration_ratio
        self.best_f = np.inf
        self.best_x = None

    def __call__(self, func):
        lb, ub = func.bounds.lb, func.bounds.ub

        for i in range(self.budget):
            if np.random.rand() < self.exploration_ratio:
                x = np.random.uniform(lb, ub, self.dim)
            else:
                if self.best_x is None:
                    x = np.random.uniform(lb, ub, self.dim)
                else:
                    x = self.best_x + np.random.normal(0, self.variance, self.dim)
                    x = np.clip(x, lb, ub)

            f = func(x)
            if f < self.best_f:
                self.best_f = f
                self.best_x = x
                self.variance *= self.reduction_factor  #Reduce variance only after a successful exploitation

        return self.best_f, self.best_x

