import numpy as np

class SimplifiedAPSO:
    def __init__(self, budget=10000, dim=10, w_start=0.9, w_end=0.4):
        self.budget = budget
        self.dim = dim
        self.w_start = w_start
        self.w_end = w_end

    def __call__(self, func):
        swarm = np.random.uniform(-5, 5, size=(30, self.dim))
        velocities = np.zeros((30, self.dim))
        pbest = swarm[:]
        gbest = min(swarm, key=func)

        for i in range(self.budget):
            w = self.w_start - i * (self.w_start - self.w_end) / self.budget
            r1, r2 = np.random.rand(2, 30, self.dim)
            velocities = w * velocities + (r1 * (pbest - swarm) + r2 * (gbest - swarm))
            swarm += velocities

            for j in range(len(swarm)):
                if func(swarm[j]) < func(pbest[j]):
                    pbest[j] = swarm[j]
                if func(swarm[j]) < func(gbest):
                    gbest = swarm[j]
        return func(gbest), gbest

