class ImprovedAdaptiveRandomSearch:
    def __init__(self, budget=10000, dim=10, init_mutation_rate=1.0, restart_probability=0.2):
        self.budget = budget
        self.dim = dim
        self.init_mutation_rate = init_mutation_rate
        self.restart_probability = restart_probability

    def __call__(self, func):
        self.f_opt = np.Inf
        self.x_opt = np.random.uniform(func.bounds.lb, func.bounds.ub, self.dim)
        mutation_rate = self.init_mutation_rate

        for i in range(self.budget):
            if np.random.rand() < self.restart_probability:
                # Local restart with higher exploration rate
                x = np.random.uniform(func.bounds.lb, func.bounds.ub, self.dim)
            else:
                x = self.x_opt + mutation_rate * np.random.normal(0, 1, self.dim)
                x = np.clip(x, func.bounds.lb, func.bounds.ub)

            f = func(x)
            if f < self.f_opt:
                self.f_opt = f
                self.x_opt = x
                mutation_rate *= 1.05
            else:
                mutation_rate *= 0.95
        return self.f_opt, self.x_opt

