class GuidedGaussianSearch:
    def __init__(self, budget=10000, dim=10, initial_sigma=2.0, shrink_rate=0.95, min_sigma=0.1):
        self.budget = budget
        self.dim = dim
        self.sigma = initial_sigma * np.ones(dim)
        self.shrink_rate = shrink_rate
        self.min_sigma = min_sigma
        self.best_solution = None
        self.best_fitness = float('inf')

    def __call__(self, func):
        bounds = np.array([func.bounds.lb, func.bounds.ub])

        for i in range(self.budget):
            if self.best_solution is None:
                x = np.random.uniform(bounds[0], bounds[1], self.dim)
            else:
                x = np.random.normal(self.best_solution, self.sigma)
                x = np.clip(x, bounds[0], bounds[1])

            fitness = func(x)
            if fitness < self.best_fitness:
                self.best_fitness = fitness
                self.best_solution = x
            else:
                self.sigma *= self.shrink_rate
                self.sigma = np.maximum(self.sigma, self.min_sigma * np.ones(self.dim))

        return self.best_fitness, self.best_solution

import numpy as np

class PSOLocalSearch:
    def __init__(self, budget=10000, dim=10, pso_particles=30, pso_iterations=50):
        self.budget = budget
        self.dim = dim
        self.pso_particles = pso_particles
        self.pso_iterations = pso_iterations
        self.bounds = (-5.0, 5.0)

    def initialize_population(self):
        return np.random.uniform(self.bounds[0], self.bounds[1], (self.pso_particles, self.dim))

    def evaluate_population(self, population, func):
        fitness_values = [func(ind) for ind in population]
        return np.array(fitness_values), population[np.argmin(fitness_values)]

    def update_velocities_positions(self, particles, velocities, pbest, gbest, w=0.7, c1=1.5, c2=1.5):
        r1 = np.random.rand(*velocities.shape)
        r2 = np.random.rand(*velocities.shape)
        velocities = w * velocities + c1 * r1 * (pbest - particles) + c2 * r2 * (gbest - particles)
        particles = np.clip(particles + velocities, self.bounds[0], self.bounds[1])
        return velocities, particles

    def local_search(self, solution, func, max_iter=10):
        for _ in range(max_iter):
            neighbor = solution + np.random.uniform(-0.1, 0.1, self.dim)
            neighbor = np.clip(neighbor, self.bounds[0], self.bounds[1])
            if func(neighbor) < func(solution):
                solution = neighbor
        return solution

    def __call__(self, func):
        population = self.initialize_population()
        fitness_values, pbest_global = self.evaluate_population(population, func)
        gbest_global = pbest_global

        for _ in range(self.pso_iterations):
            if self.budget <= 0:
                break

            velocities = np.zeros_like(population)

            for i in range(self.pso_particles):
                if fitness_values[i] < func(pbest_global):
                    pbest_global = population[i]

                if fitness_values[i] < func(gbest_global):
                    gbest_global = population[i]

                velocities[i], population[i] = self.update_velocities_positions(
                    population[i:i+1], velocities[i:i+1], pbest_global, gbest_global
                )
                self.budget -= 1

            if self.budget <= 0:
                break

        best_solution = gbest_global
        for _ in range(self.pso_particles):
            best_solution = self.local_search(best_solution, func)
            self.budget -= 1

        return func(best_solution), best_solution

import numpy as np

class RefinedPSOLocalSearch:
    def __init__(self, budget=10000, dim=10, swarm_size=30):
        self.budget = budget
        self.dim = dim
        self.swarm_size = swarm_size
        self.bounds = (-5.0, 5.0)

    def initialize_population(self):
        return np.random.uniform(self.bounds[0], self.bounds[1], (self.swarm_size, self.dim))

    def evaluate_population(self, population, func):
        fitness_values = [func(ind) for ind in population]
        best_idx = np.argmin(fitness_values)
        return np.array(fitness_values), population[best_idx]

    def update_positions(self, particles, velocities, pbest, gbest, w=0.7, c1=2.0, c2=2.0):
        r1 = np.random.rand(*velocities.shape)
        r2 = np.random.rand(*velocities.shape)
        velocities = (w * velocities +
                      c1 * r1 * (pbest - particles) +
                      c2 * r2 * (gbest - particles))
        particles = np.clip(particles + velocities, self.bounds[0], self.bounds[1])
        return velocities, particles

    def local_search(self, solution, func, max_iter=5):
        for _ in range(max_iter):
            neighbor = solution + np.random.uniform(-0.1, 0.1, self.dim)
            neighbor = np.clip(neighbor, self.bounds[0], self.bounds[1])
            if func(neighbor) < func(solution):
                solution = neighbor
        return solution

    def __call__(self, func):
        population = self.initialize_population()
        fitness_values, gbest_global = self.evaluate_population(population, func)

        for _ in range(self.budget // self.swarm_size):
            if self.budget <= 0:
                break

            velocities = np.zeros_like(population)

            pbests = np.copy(population)

            for i in range(self.swarm_size):
                if fitness_values[i] < func(pbests[i]):
                    pbests[i] = population[i]

                if fitness_values[i] < func(gbest_global):
                    gbest_global = population[i]

                velocities[i], population[i] = self.update_positions(
                    population[i:i+1], velocities[i:i+1], pbests[i], gbest_global
                )
                self.budget -= 1

            if self.budget <= 0:
                break

        best_solution = gbest_global
        for _ in range(self.swarm_size):
            best_solution = self.local_search(best_solution, func)
            if self.budget <= 0:
                break

        return func(best_solution), best_solution

import numpy as np

class EnhancedPSOLocalSearch:
    def __init__(self, budget=10000, dim=10, particles=30):
        self.budget = budget
        self.dim = dim
        self.particles = particles
        self.bounds = (-5.0, 5.0)

    def initialize_population(self):
        return np.random.uniform(self.bounds[0], self.bounds[1], (self.particles, self.dim))

    def evaluate_population(self, population, func):
        fitness_values = [func(ind) for ind in population]
        best_idx = np.argmin(fitness_values)
        return np.array(fitness_values), population[best_idx]

    def update_velocities_positions(self, particles, velocities, pbest, gbest, w=0.7, c1=2.0, c2=2.0):
        r1 = np.random.rand(*velocities.shape)
        r2 = np.random.rand(*velocities.shape)
        velocities = w * velocities + c1 * r1 * (pbest - particles) + c2 * r2 * (gbest - particles)
        particles = np.clip(particles + velocities, self.bounds[0], self.bounds[1])
        return velocities, particles

    def local_search(self, solution, func, max_iter=5):
        for _ in range(max_iter):
            neighbor = solution + np.random.uniform(-0.2, 0.2, self.dim)
            neighbor = np.clip(neighbor, self.bounds[0], self.bounds[1])
            if func(neighbor) < func(solution):
                solution = neighbor
        return solution

    def __call__(self, func):
        population = self.initialize_population()
        fitness_values, gbest_global = self.evaluate_population(population, func)
        pbests = population.copy()

        for _ in range(self.budget // self.particles):
            if self.budget <= 0:
                break

            velocities = np.zeros_like(population)

            for i in range(self.particles):
                if fitness_values[i] < func(pbests[i]):
                    pbests[i] = population[i]

                if fitness_values[i] < func(gbest_global):
                    gbest_global = population[i]

                velocities[i], population[i] = self.update_velocities_positions(
                    population[i:i+1], velocities[i:i+1], pbests[i], gbest_global
                )
                self.budget -= 1

            if self.budget <= 0:
                break

        best_solution = gbest_global
        for _ in range(5):
            best_solution = self.local_search(best_solution, func)
            self.budget -= 1

        return func(best_solution), best_solution

import numpy as np

class EnhancedPSOLocalSearch:
    def __init__(self, budget=10000, dim=10, num_particles=30, w=0.7, c1=2.0, c2=2.0, max_iter=50, local_search_iter=10):
        self.budget = budget
        self.dim = dim
        self.num_particles = num_particles
        self.w = w
        self.c1 = c1
        self.c2 = c2
        self.max_iter = max_iter
        self.local_search_iter = local_search_iter
        self.bounds = (-5.0, 5.0)

    def initialize_population(self):
        return np.random.uniform(self.bounds[0], self.bounds[1], (self.num_particles, self.dim))

    def evaluate_fitness(self, population, func):
        fitness_values = [func(ind) for ind in population]
        return np.array(fitness_values), population[np.argmin(fitness_values)]

    def update_particles(self, particles, velocities, pbest, gbest):
        r1 = np.random.rand(*velocities.shape)
        r2 = np.random.rand(*velocities.shape)
        velocities = self.w * velocities + self.c1 * r1 * (pbest - particles) + self.c2 * r2 * (gbest - particles)
        particles = np.clip(particles + velocities, self.bounds[0], self.bounds[1])
        return velocities, particles

    def local_search(self, solution, func):
        for _ in range(self.local_search_iter):
            neighbor = solution + np.random.uniform(-0.1, 0.1, self.dim)
            neighbor = np.clip(neighbor, self.bounds[0], self.bounds[1])
            if func(neighbor) < func(solution):
                solution = neighbor
        return solution

    def __call__(self, func):
        population = self.initialize_population()
        fitness_values, pbest_global = self.evaluate_fitness(population, func)
        gbest_global = pbest_global

        for _ in range(self.max_iter):
            if self.budget <= 0:
                break

            velocities = np.zeros_like(population)

            for i in range(self.num_particles):
                if fitness_values[i] < func(pbest_global):
                    pbest_global = population[i]

                if fitness_values[i] < func(gbest_global):
                    gbest_global = population[i]

                velocities[i], population[i] = self.update_particles(
                    population[i:i+1], velocities[i:i+1], pbest_global, gbest_global
                )
                self.budget -= 1

            if self.budget <= 0:
                break

        best_solution = gbest_global
        for _ in range(self.num_particles):
            best_solution = self.local_search(best_solution, func)
            self.budget -= 1

        return func(best_solution), best_solution

import numpy as np

class EnhancedSimulatedAnnealing:
    def __init__(self, budget=10000, dim=10, temp_start=1000, alpha=0.95):
        self.budget = budget
        self.dim = dim
        self.temp_start = temp_start
        self.alpha = alpha

    def __call__(self, func):
        x_current = np.random.uniform(func.bounds.lb, func.bounds.ub)
        f_current = func(x_current)

        for i in range(self.budget):
            temp = self.temp_start * self.alpha ** (i / self.budget)
            x_new = np.clip(np.random.normal(x_current, 0.1), func.bounds.lb, func.bounds.ub)
            f_new = func(x_new)

            if (f_new < f_current) or (np.exp((f_current - f_new) / temp) > np.random.rand()):
                x_current = x_new
                f_current = f_new

            # Local search to improve solution
            if i % int(self.budget * 0.1) == 0:
                x_current = self.local_search(func, x_current)
                f_current = func(x_current)

        return f_current, x_current

    def local_search(self, func, x):
        directions = np.identity(self.dim) * 0.1
        for i in range(len(directions)):
            y = np.clip(x + directions[i], func.bounds.lb, func.bounds.ub)
            f_y = func(y)
            if f_y < func(x):
                x = y
        return x

import numpy as np

class AdaptiveDEOptimizer:
    def __init__(self, budget=10000, dim=10):
        self.budget = budget
        self.dim = dim

    def __call__(self, func):
        population_size = int(np.sqrt(self.budget))
        population = np.random.uniform(-5.0, 5.0, (population_size, self.dim))
        fitness = np.array([func(individual) for individual in population])
        best_idx = np.argmin(fitness)
        best = population[best_idx]

        CR_min, CR_max = 0.1, 0.9  # Adaptive crossover rate range

        for _ in range(self.budget):
            CR = np.random.uniform(CR_min, CR_max)  # Adaptive crossover rate

            for i in range(population_size):
                a, b, c = np.random.choice(population_size, 3, replace=False)
                mutant = best + np.random.rand() * (population[a] - population[b])  # Improved mutation strategy
                trial = self.simplex_crossover(population[i], mutant, CR)  # Simplex crossover
                trial_fitness = func(trial)

                if trial_fitness < fitness[i]:
                    population[i] = trial
                    fitness[i] = trial_fitness
                    if trial_fitness < fitness[best_idx]:
                        best_idx = i
                        best = trial

        return fitness[best_idx], best

    def simplex_crossover(self, x1, x2, CR):
        j_rand = np.random.randint(self.dim)
        return np.where(np.logical_or(np.random.rand(self.dim) < CR, np.arange(self.dim) == j_rand), x2, x1)

import numpy as np

class RandomLocalSearch:
    def __init__(self, budget=10000, dim=10, step_size=0.2):
        self.budget = budget
        self.dim = dim
        self.step_size = step_size  # Local refinement step size

    def __call__(self, func):
        self.f_opt = np.Inf
        self.x_opt = None

        for i in range(self.budget):
            if i < self.budget // 2:
                # Exploration phase: Random search
                x = np.random.uniform(func.bounds.lb, func.bounds.ub)
            else:
                # Exploitation phase: Local refinement around the best solution found so far
                x = self.x_opt + np.random.normal(scale=self.step_size, size=self.dim)
                x = np.clip(x, func.bounds.lb, func.bounds.ub)  # Ensure bounds are respected

            f = func(x)
            if f < self.f_opt:
                self.f_opt = f
                self.x_opt = x

        return self.f_opt, self.x_opt

import numpy as np

class AdaptiveRandomLocalSearch:
    def __init__(self, budget=10000, dim=10, initial_step_size=0.2):
        self.budget = budget
        self.dim = dim
        self.initial_step_size = initial_step_size  # Initial local refinement step size

    def __call__(self, func):
        self.f_opt = np.Inf
        self.x_opt = None
        step_size = self.initial_step_size

        for i in range(self.budget):
            if i < self.budget // 2:
                # Exploration phase: Random search
                x = np.random.uniform(func.bounds.lb, func.bounds.ub)
            else:
                # Exploitation phase: Local refinement around the best solution found so far
                x = self.x_opt + np.random.normal(scale=step_size, size=self.dim)
                x = np.clip(x, func.bounds.lb, func.bounds.ub)  # Ensure bounds are respected

            f = func(x)
            if f < self.f_opt:
                self.f_opt = f
                self.x_opt = x
                step_size *= 0.95  # Decrease step size for more local refinement
            else:
                step_size *= 1.05  # Increase step size if no improvement is found

        return self.f_opt, self.x_opt
